1/* *********************************************** 2Author :111qqz 3Created Time :2017年10月09日 星期一 21时09分36秒 4File Name :1724.cpp 5************************************************ */ 6 7#include &lt;cstdio&gt; 8#include &lt;cstring&gt; 9#include &lt;iostream&gt; 10#include &lt;algorithm&gt; 11#include &lt;vector&gt; 12#include &lt;queue&gt; 13#include &lt;set&gt; 14#include &lt;map&gt; 15#include &lt;string&gt; 16#include &lt;cmath&gt; 17#include &lt;cstdlib&gt; 18#include &lt;ctime&gt; 19#define PB push_back 20#define fst first 21#define sec second 22#define lson l,m,rt&lt;&lt;1 23#define rson m+1,r,rt&lt;&lt;1|1 24#define ms(a,x) memset(a,x,sizeof(a)) 25typedef long long LL; 26#define pi pair &lt; int ,int &gt; 27#define MP make_pair 28 29using namespace std; 30const double eps = 1E-10; 31const int dx4[4]={1,0,0,-1}; 32const int dy4[4]={0,-1,1,0}; 33const int inf = 0x3f3f3f3f; 34double a,b,l,r; 35double dblcmp(double d){ return d&lt;-eps?-1:d&gt;eps;} 36double f(double x) 37{ 38 double ret; 39 ret = sqrt((1-(x*x/a/a))*b*b); 40 return ret; 41} 42double simpson(double l,double r) 43{ 44 return (r-l)*(f(l) + f(r) + 4*f((l+r)*0.5))/6; 45} 46double di( double l,double r) 47{ 48 //cout&lt;&lt;&#34;l:&#34;&lt;&lt;l&lt;&lt;&#34; r:&#34;&lt;&lt;r&lt;&lt;endl; 49 double m = (l+r)*0.5; 50 double ans = simpson(l,r); 51 if (dblcmp(ans-simpson(l,m)-simpson(m,r))==0) return ans; 52 return di(l,m) + di(m,r); 53} 54int main() 55{ 56 #ifndef ONLINE_JUDGE 57 freopen(&#34;./in.txt&#34;,&#34;r&#34;,stdin); 58 #endif 59 int T; 60 cin&gt;&gt;T; 61 while (T--) 62 { 63 scanf(&#34;%lf %lf %lf %lf&#34;,&amp;a,&amp;b,&amp;l,&amp;r); 64 double ans = di (l,r)*2.0; 65 printf(&#34;%.3f\n&#34;,ans); 66 } 67 68 69 70 #ifndef ONLINE_JUDGE 71 fclose(stdin); 72 #endif 73 return 0; 74}

