Given an array S of n integers, find three integers in S such that the sum is closest to a given number, target. Return the sum of the three integers. You may assume that each input would have exactly one solution.
思路： 排序，然后two pointer,复杂度 O(n^2)
1/* *********************************************** 2Author :111qqz 3Created Time :2017年04月13日 星期四 16时24分28秒 4File Name :16.cpp 5************************************************ */ 6class Solution { 7 8public: 9 10 int n; 11 int threeSumClosest(vector&lt;int&gt;&amp; nums, int target) { 12	n = nums.size(); 13	sort(nums.begin(),nums.end()); 14	int mn = 0x3f3f3f3f; 15	int x,y,z; 16	for ( int i = 0 ; i &lt;=n-3 ; i++) 17	{ 18	int head = i+1; 19	int tail = n-1; 20	int tar = target - nums[i]; 21	while (head&lt;tail) 22	{ 23	int cur = target-nums[i]-nums[head]-nums[tail]; 24	if (abs(cur)&lt;mn) 25	{ 26	mn = abs(cur); 27	x = nums[i]; 28	y = nums[head]; 29	z = nums[tail]; 30	} 31	if (nums[head]+nums[tail]==tar) return target; 32	if (nums[head]+nums[tail]&lt;tar) head++; 33	else tail--; 34	} 35	} 36	return x + y + z; 37 38 39 40 41 } 42 43};

Given two integers n and k, return all possible combinations of k numbers out of 1 &hellip; n.
思路：就是枚举子集，根据集合的大小剪枝。。。最后只要集合大小为k的集合
1/* *********************************************** 2Author :111qqz 3Created Time :2017年04月13日 星期四 15时25分37秒 4File Name :77.cpp 5************************************************ */ 6class Solution { 7public: 8 set&lt;vector&lt;int&gt; &gt;se; 9 int B[1005]; 10 vector&lt;vector&lt;int&gt; &gt;res; 11 void get_subset(int n,int *B,int cur,int cnt,int k) 12 { 13	if (cur==n) 14	{ 15	vector&lt;int&gt;tmp; 16	for ( int i = 0 ; i &lt; n ; i++) 17	if (B[i]) tmp.push_back(i+1); 18	if (tmp.size()==k) 19	se.insert(tmp); 20	return ; 21	} 22	if (cnt&lt;k) 23	{ 24	B[cur] = 1; 25	get_subset(n,B,cur+1,cnt+1,k); 26	} 27	B[cur] = 0 ; 28	get_subset(n,B,cur+1,cnt,k); 29 } 30 vector&lt;vector&lt;int&gt;&gt; combine(int n, int k) { 31	get_subset(n,B,0,0,k); 32	for (auto &amp;it:se) 33	{ 34	res.push_back(it); 35	} 36	return res; 37 } 38};

Given a collection of numbers that might contain duplicates, return all possible unique permutations.__
思路：和leet code 46 类似，最后用set去个重即可。。
1/* *********************************************** 2Author :111qqz 3Created Time :2017年04月13日 星期四 15时00分48秒 4File Name :47.cpp 5************************************************ */ 6class Solution { 7 8public: 9 void solve( vector&lt;int&gt;&amp;nums) 10 { 11	int n = nums.size(); 12	if (n==0) return; 13	int k = -1; 14	for ( int i = n-2 ; i &gt;= 0 ; i--) 15	{ 16	if (nums[i]&lt;nums[i+1]) 17	{ 18	k = i; 19	break; 20	} 21	} 22	if (k==-1) 23	{ 24	reverse(nums.begin(),nums.end()); 25	return; 26	} 27	int l = -1; 28	for ( int i = n-1 ; i &gt;k ; i--) 29	{ 30	if (nums[k]&lt;nums[i]) 31	{ 32	l = i; 33	break; 34	} 35	} 36	swap(nums[l],nums[k]); 37	reverse(nums.begin()+k+1,nums.end()); 38 } 39 40 void pr (vector&lt;int&gt; &amp;nums) 41 { 42	int siz = nums.size(); 43	for ( int i = 0 ; i &lt; siz; i++) 44	printf(&#34;%d%c&#34;,nums[i],i==siz-1?&#39;\n&#39;:&#39; &#39;); 45 } 46 vector&lt;vector&lt;int&gt;&gt; permuteUnique(vector&lt;int&gt;&amp; nums) { 47	set&lt;vector&lt;int&gt; &gt;se; 48	vector&lt;vector&lt;int&gt; &gt;res; 49	int n = nums.size(); 50	int total = 1 ; 51	for ( int i = 2 ; i &lt;= n ; i++) total*=i; 52 53	for ( int i = 1 ; i &lt;= total ; i++) 54	{ 55	se.insert(nums); 56//	pr(nums); 57	solve(nums); 58	} 59	for ( auto &amp;it :se) 60	{ 61	res.push_back(it); 62	} 63	return res; 64 } 65 66};

Given a collection of distinct numbers, return all possible permutations.
思路：调用n-1次 leetcode 31 解题报告 中提到的算法即可。。。
1/* *********************************************** 2Author :111qqz 3Created Time :2017年04月13日 星期四 14时49分34秒 4File Name :46.cpp 5 ************************************************ */ 6class Solution { 7 8 public: 9 10	void solve(vector&lt;int&gt; &amp;nums) 11	{ 12	int n = nums.size(); 13	if (n==0) return; 14	int k = -1; 15	for ( int i = n-2 ; i &gt;= 0 ; i--) 16	{ 17	if (nums[i]&lt;nums[i+1]) 18	{ 19	k = i ; 20	break; 21	} 22	} 23	if (k==-1) 24	{ 25	reverse(nums.begin(),nums.end()); 26	return; 27	} 28	int l = -1; 29	for ( int i = n-1 ; i &gt; k ; i-- ) 30	{ 31	if (nums[k]&lt;nums[i]) 32	{ 33	l = i ; 34	break; 35	} 36	} 37	swap(nums[l],nums[k]); 38	reverse(nums.begin()+k+1,nums.end()); 39	} 40	vector&lt;vector&lt;int&gt;&gt; permute(vector&lt;int&gt;&amp; nums) { 41	vector&lt;vector&lt;int&gt; &gt;res; 42	int n = nums.size(); 43	int total = 1; 44	for ( int i = 2 ; i &lt;= n ; i++) total*=i; 45	for ( int i = 1 ; i &lt;= total; i++) 46	{ 47	res.push_back(nums); 48	solve(nums); 49	} 50 51	return res; 52	} 53 54};

Given a set of candidate numbers (C) (without duplicates) and a target number (T), find all unique combinations in C where the candidate numbers sums to T.
The same repeated number may be chosen from C unlimited number of times.
Note:
* All numbers (including target) will be positive integers. * The solution set must not contain duplicate combinations. 题意：给n个数，求所有的组合，和为定值，每个数可以重复用)
思路：。。。。一开始用顺着枚举子集的思路。。。发现。。并不好搞。。。？还不如直接dfs&hellip;
1/* *********************************************** 2Author :111qqz 3Created Time :2017年04月13日 星期四 00时06分12秒 4File Name :39.cpp 5************************************************ */ 6class Solution { 7public: 8 9 vector&lt;vector&lt;int&gt; &gt;res; 10 vector&lt;int&gt;tmp; 11 int n; 12 //思路：dfs 13 void dfs( int start,int cur,vector&lt;int&gt; &amp;nums) 14 { 15	if (cur==0) 16	{ 17	res.push_back(tmp); 18	return ; 19	} 20	else if (cur&lt;0) return; 21	else 22	{ 23	for ( int i = start ; i &lt; n ; i++) 24	{ 25	tmp.push_back(nums[i]); 26	dfs(i,cur-nums[i],nums); 27	tmp.erase(tmp.begin()+tmp.size()-1); 28	} 29	} 30 } 31 32 vector&lt;vector&lt;int&gt;&gt; combinationSum(vector&lt;int&gt;&amp; nums, int target) { 33	n = nums.size(); 34	if (n==0) return res; 35	dfs(0,target,nums); 36	return res; 37 } 38};

Given a matrix of m x n elements (m rows, n columns), return all elements of the matrix in spiral order.
思路：。。。再次让我回想起高一的暑假。。。。
1/* *********************************************** 2Author :111qqz 3Created Time :2017年04月11日 星期二 19时42分05秒 4File Name :54.cpp 5************************************************ */ 6class Solution { 7public: 8 int n,m; //0右，1下，2左，3上 9 int cal( int &amp;x,int &amp;y,int dir,vector&lt;vector&lt;bool&gt; &gt; &amp; vis) 10 { 11	if (dir==0) 12	{ 13	if (y&lt;=n-2&amp;&amp;!vis[x][y+1]) y++; 14	else 15	{ 16	dir++; 17	x++; 18	} 19	return dir; 20	} 21	if (dir==1) 22	{ 23	if (x&lt;=m-2&amp;&amp;!vis[x+1][y]) x++; 24	else 25	{ 26	dir++; 27	y--; 28	} 29	return dir; 30	} 31	if (dir==2) 32	{ 33	if (y&gt;=1&amp;&amp;!vis[x][y-1]) y--; 34	else 35	{ 36	dir++; 37	x--; 38	} 39	return dir; 40	} 41	if (dir==3) 42	{ 43	if (x&gt;=1&amp;&amp;!vis[x-1][y]) x--; 44	else 45	{ 46	dir = 0 ; 47	y++; 48	} 49	return dir; 50	} 51 } 52 vector&lt;int&gt; spiralOrder(vector&lt;vector&lt;int&gt;&gt;&amp; matrix) { 53	vector&lt;int&gt;res; 54	m = matrix.size(); 55	if (m==0) return res; 56	n = matrix[0].size(); 57	if (n==0) return res; 58	vector&lt;vector&lt;bool&gt; &gt;vis(m,vector&lt;bool&gt;(n,false)); 59	int x,y,dir; 60	x = y = dir = 0 ; 61	for ( int i = 0 ; i &lt; n*m ; i++) 62	{ 63	printf(&#34;x:%d y:%d\n&#34;,x,y); 64	res.push_back(matrix[x][y]); 65	vis[x][y] = true; 66	dir = cal(x,y,dir,vis); 67	} 68	return res; 69 } 70};

Given an integer n, generate a square matrix filled with elements from 1 to _n_2 in spiral order.
思路：仿佛回到高一的那个暑假。。。
1/* *********************************************** 2Author :111qqz 3Created Time :2017年04月11日 星期二 18时52分15秒 4File Name :59.cpp 5************************************************ */ 6class Solution { 7 8public: 9 10 11 int ok (int dir, int &amp;x,int &amp;y,int n,vector&lt;vector&lt;int&gt; &gt;&amp;res) // 0右，1下，2左，3上 12 { 13	if (dir==0) 14	{ 15	if (y&lt;=n-2&amp;&amp;res[x][y+1]==0) y++; 16	else 17	{ 18	dir++; 19	x++; 20	} 21	return dir; 22	} 23	if (dir==1) 24	{ 25	if (x&lt;=n-2&amp;&amp;res[x+1][y]==0) x++; 26	else 27	{ 28	dir++; 29	y--; 30	} 31	return dir; 32	} 33	if (dir==2) 34	{ 35	if (y&gt;=1&amp;&amp;res[x][y-1]==0) y--; 36	else 37	{ 38	dir++; 39	x--; 40	} 41	return dir; 42	} 43	if (dir==3) 44	{ 45	if (x&gt;=1&amp;&amp;res[x-1][y]==0) x--; 46	else 47	{ 48	dir = 0 ; 49	y++; 50	} 51	return dir; 52	} 53 } 54 55 56 57 58 vector&lt;vector&lt;int&gt;&gt; generateMatrix(int n) { 59 60	vector&lt;vector&lt;int&gt; &gt;res(n,vector&lt;int&gt;(n,0)); 61	int dir = 0; 62	int x,y; 63	x = y = 0 ; 64	for ( int i = 0 ; i &lt; n*n ; i++) 65	{ 66	res[x][y] = i+1; 67//	printf(&#34; x:%d y: %d\n&#34;,x,y); 68	dir = ok (dir,x,y,n,res); 69	} 70	return res; 71 72 73 } 74 75};

Given a 2D board and a word, find if the word exists in the grid.
The word can be constructed from letters of sequentially adjacent cell, where &ldquo;adjacent&rdquo; cells are those horizontally or vertically neighboring. The same letter cell may not be used more than once.
思路：dfs即可。记得要回溯一下&hellip;
1/* *********************************************** 2Author :111qqz 3Created Time :2017年04月07日 星期五 14时32分54秒 4File Name :79.cpp 5************************************************ */ 6class Solution { 7 8public: 9 10 int n,m; 11 const int dx4[4]={1,-1,0,0}; 12 const int dy4[4]={0,0,-1,1}; 13 bool vis[1005][1005]; 14 int len; 15 16 bool yes( int x,int y) 17 { 18	if (x&gt;=0&amp;&amp;x&lt;=n-1&amp;&amp;y&gt;=0&amp;&amp;y&lt;=m-1) return true; 19	return false; 20 } 21 22 bool dfs( int x,int y,int cur,vector&lt;vector&lt;char&gt; &gt; &amp; maze,string &amp; st) 23 { 24//	printf(&#34;x:%d y:%d cur : %d\n&#34;,x,y,cur); 25	if (cur&gt;=len) return true; 26	for ( int i = 0 ; i &lt; 4 ; i++) 27	{ 28	int nx = x + dx4[i]; 29	int ny = y + dy4[i]; 30	if (!yes(nx,ny)) continue; 31	if (vis[nx][ny]) continue; 32	if (maze[nx][ny]!=st[cur]) continue; 33	vis[nx][ny] = true; 34	bool res = dfs(nx,ny,cur+1,maze,st); 35	if (res) return true; 36	vis[nx][ny] = false ;//好像还要回溯一下啊？ 37	} 38	return false; 39 } 40 41 bool exist(vector&lt;vector&lt;char&gt;&gt;&amp; board, string word) { 42	n = board.size(); 43	if (n==0) return false; 44	m = board[0].size(); 45	if (m==0) return false; 46	len = word.length(); 47	cout&lt;&lt;&#34;len:&#34;&lt;&lt;len&lt;&lt;endl; 48	char beg = word[0]; 49	for ( int i = 0 ; i &lt; n ; i++) 50	for ( int j = 0 ; j &lt; m ; j++) 51	if (board[i][j]==beg) 52	{ 53	memset(vis,false,sizeof(vis)); 54	//起点忘记打标记了。。。智力-2.。。 55	vis[i][j] = true; 56	bool ok = dfs(i,j,1,board,word); 57	cout&lt;&lt;&#34;ok:&#34;&lt;&lt;ok&lt;&lt;endl; 58	if (ok) return true; 59	} 60	return false; 61 62 63 } 64 65};

