1/* *********************************************** 2Author :111qqz 3Created Time :2017年03月30日 星期四 10时17分40秒 4File Name :code/toutiao4.cpp 5************************************************ */ 6 7#include &lt;cstdio&gt; 8#include &lt;cstring&gt; 9#include &lt;iostream&gt; 10#include &lt;algorithm&gt; 11#include &lt;vector&gt; 12#include &lt;queue&gt; 13#include &lt;set&gt; 14#include &lt;map&gt; 15#include &lt;string&gt; 16#include &lt;cmath&gt; 17#include &lt;cstdlib&gt; 18#include &lt;ctime&gt; 19#define fst first 20#define sec second 21#define lson l,m,rt&lt;&lt;1 22#define rson m+1,r,rt&lt;&lt;1|1 23#define ms(a,x) memset(a,x,sizeof(a)) 24typedef long long LL; 25#define pi pair &lt; int ,int &gt; 26#define MP make_pair 27 28using namespace std; 29const double eps = 1E-8; 30const int dx4[4]={1,0,0,-1}; 31const int dy4[4]={0,-1,1,0}; 32const int inf = 0x3f3f3f3f; 33int bin_y[80],cnt_y=0; 34int bin_x[80],cnt_x=0; 35int bin_k[80],cnt_k=0; 36int x,k; 37void bin( int x) 38{ 39 while (x) 40 { 41	bin_x[++cnt_x] = x%2; 42	x/=2; 43 } 44} 45void bin2( int x) 46{ 47 while (x) 48 { 49	bin_k[++cnt_k] = x%2; 50	x/=2; 51 } 52} 53int main() 54{ 55	#ifndef ONLINE_JUDGE 56	freopen(&#34;code/in.txt&#34;,&#34;r&#34;,stdin); 57 #endif 58	//打表得到的规律:对于x的二进制表示中,某位为1,那么对应的y的位置上一定为0; 59	//如果某位为0,那么可以为1,可以为0. 60	//所以保留x中,为1的位置,将k的二进制填写到为0的位置上,最后得到的数就是ans... 61	//全程口胡,写一发先. 62	cin&gt;&gt;x&gt;&gt;k; 63	bin(x); 64	bin2(k); 65	ms(bin_y,-1); 66	int cur = 0 ; 67	for ( int i = 1 ; i &lt;= 60 ; i++) 68	{ 69	if (bin_x[i]==0) 70	{ 71	bin_x[i] = bin_k[++cur]; 72	} 73	} 74	unsigned long long ans = 0 ; 75	unsigned long long p = 1; 76	for ( int i = 1 ; i &lt;= 60 ; i++) 77	{ 78	ans = ans + p * bin_x[i]; 79//	cout&lt;&lt;bin_x[i]&lt;&lt;endl; 80	// cout&lt;&lt;&#34;p:&#34;&lt;&lt;p&lt;&lt;endl; 81	p&lt;&lt;=1; 82	} 83	cout&lt;&lt;ans-x&lt;&lt;endl; 84 #ifndef ONLINE_JUDGE 85 fclose(stdin); 86 #endif 87 return 0; 88}

有一个由很多木棒构成的集合，每个木棒有对应的长度，请问能否用集合中的这些木棒以某个顺序首尾相连构成一个面积大于 0 的简单多边形且所有木棒都要用上，简单多边形即不会自交的多边形。
初始集合是空的，有两种操作，要么给集合添加一个长度为 L 的木棒，要么删去集合中已经有的某个木棒。每次操作结束后你都需要告知是否能用集合中的这些木棒构成一个简单多边形。
输入描述: # 每组测试用例仅包含一组数据，每组数据第一行为一个正整数 n 表示操作的数量(1 ≤ n ≤ 50000) ， 接下来有n行，每行第一个整数为操作类型 i (i ∈ {1,2})，第二个整数为一个长度 L(1 ≤ L ≤ 1,000,000,000)。如果 i=1 代表在集合内插入一个长度为 L 的木棒，如果 i=2 代表删去在集合内的一根长度为 L 的木棒。输入数据保证删除时集合中必定存在长度为 L 的木棒，且任意操作后集合都是非空的。
输出描述: # 对于每一次操作结束有一次输出，如果集合内的木棒可以构成简单多边形，输出 &ldquo;Yes&rdquo; ，否则输出 &ldquo;No&rdquo;。
