1/* *********************************************** 2Author :111qqz 3Created Time :Tue 01 Nov 2016 08:00:49 PM CST 4File Name :code/hdu/2522.cpp 5************************************************ */ 6#include &lt;cstdio&gt; 7#include &lt;cstring&gt; 8#include &lt;iostream&gt; 9#include &lt;algorithm&gt; 10#include &lt;vector&gt; 11#include &lt;queue&gt; 12#include &lt;set&gt; 13#include &lt;map&gt; 14#include &lt;string&gt; 15#include &lt;cmath&gt; 16#include &lt;cstdlib&gt; 17#include &lt;ctime&gt; 18#define fst first 19#define sec second 20#define lson l,m,rt&lt;&lt;1 21#define rson m+1,r,rt&lt;&lt;1|1 22#define ms(a,x) memset(a,x,sizeof(a)) 23typedef long long LL; 24#define pi pair &lt; int ,int &gt; 25#define MP make_pair 26using namespace std; 27const double eps = 1E-8; 28const int dx4[4]={1,0,0,-1}; 29const int dy4[4]={0,-1,1,0}; 30const int inf = 0x3f3f3f3f; 31const int N=1E6+7; 32int vis[N]; 33int n; 34int cnt = 0; 35void solve( int n) 36{ 37 if (n&lt;0) 38 { 39	printf(&#34;-&#34;); 40	n = -n; 41 } 42 if (n==1) 43 { 44	printf(&#34;1&#34;); 45	return; 46 } 47 int x; 48 printf(&#34;0.&#34;); 49 for ( x = 10; x ;x*=10) 50 { 51	if (vis[x]==cnt) break; 52	vis[x] = cnt; 53	printf(&#34;%d&#34;,x/n); 54	x%=n; 55 } 56 puts(&#34;&#34;); 57} 58int main() 59{ 60	#ifndef ONLINE_JUDGE 61	freopen(&#34;code/in.txt&#34;,&#34;r&#34;,stdin); 62 #endif 63	int T; 64	scanf(&#34;%d&#34;,&amp;T); 65	while (T--) 66	{ 67	scanf(&#34;%d&#34;,&amp;n); 68	cnt++; 69	solve(n); 70	} 71 #ifndef ONLINE_JUDGE 72 fclose(stdin); 73 #endif 74 return 0; 75}

题目链接
题意：定义s(k)为将n分成k个正整数的划分数，给出n，问s(1) + s(2) + &hellip; + s(n-1) + s(n)是多少，结果9+7，其中n&lt;=10^100000。
思路：首先化简要求的式子。
根据隔板法_维基百科
现在有10个球，要放进3个盒子里
●●●●●●●●●●
隔2个板子，把10个球被隔开成3个部分
●|●|●●●●●●●●、●|●●|●●●●●●●、●|●●●|●●●●●●、●|●●●●|●●●●●、●|●●●●●|●●●●、●|●●●●●●|●●●、&hellip;&hellip;
如此类推，10个球放进3个盒子的方法总数为{ n个球放进k个盒子的方法总数为{ 问题等价于求{ 的可行解数，其中 为正整数。
于是问题转化成：
n个木棍，n-1个缝，
分成1份则是C(n-1,0);
分成2份则是C(n-1,1);
分成3份则是C(n-1,2);
&hellip;
分成n份则是C(n-1,n-1);
ans = sum( C(n-1,i) ) (0&lt;=i&lt;=n-1)
=2^(n-1);
这是我能理解的得到2^(n-1)的方式。。。
看到有好多人说这个结论是显然的。。。求指教（说这是个结论记住就好的就算了23333）
接下来，就是求A=2^(n-1)9+7的问题了。。。
根据指数循环节公式A=2^((n-1)%(mod-1))*2^(mod-1)%mod (其中mod=1E9+7)
由于gcd(2,1E9+7)=1,根据费马小定理2^(mod-1)%mod=1，因此A=2^((n-1)%(mod-1))
然后快速幂搞之。
1/* *********************************************** 2Author :111qqz 3Created Time :Wed 26 Oct 2016 06:22:39 PM CST 4File Name :code/hdu/4704.cpp 5************************************************ */ 6 7#include &lt;cstdio&gt; 8#include &lt;cstring&gt; 9#include &lt;iostream&gt; 10#include &lt;algorithm&gt; 11#include &lt;vector&gt; 12#include &lt;queue&gt; 13#include &lt;set&gt; 14#include &lt;map&gt; 15#include &lt;string&gt; 16#include &lt;cmath&gt; 17#include &lt;cstdlib&gt; 18#include &lt;ctime&gt; 19#define fst first 20#define sec second 21#define lson l,m,rt&lt;&lt;1 22#define rson m+1,r,rt&lt;&lt;1|1 23#define ms(a,x) memset(a,x,sizeof(a)) 24typedef long long LL; 25#define pi pair &lt; int ,int &gt; 26#define MP make_pair 27 28using namespace std; 29const double eps = 1E-8; 30const int dx4[4]={1,0,0,-1}; 31const int dy4[4]={0,-1,1,0}; 32const int inf = 0x3f3f3f3f; 33const int N=1E5+7; 34const LL mod = 1E9+7; 35char st[N]; 36int len; 37LL n; 38LL ksm(LL a,LL b) 39{ 40 LL res = 1LL; 41 while (b&gt;0) 42 { 43	if (b&amp;1) res = (res * a) % mod; 44	b = b &gt;&gt; 1LL; 45	a = ( a*a ) % mod; 46 } 47 return res; 48} 49int main() 50{ 51	#ifndef ONLINE_JUDGE 52	freopen(&#34;code/in.txt&#34;,&#34;r&#34;,stdin); 53 #endif 54 55	while (~scanf(&#34;%s&#34;,st)) 56	{ 57	len = strlen(st); 58	n = 0 ; 59	for ( int i = 0 ; i &lt; len ; i++) 60	{ 61	LL val = st[i]-&#39;0&#39;; 62	n = ((n * 10LL)%(mod-1) + val)% (mod-1); 63	} 64	n = (n-1+mod-1)%(mod-1); 65	LL ans = ksm( 2,n ); 66	printf(&#34;%lld\n&#34;,ans); 67	} 68 69 #ifndef ONLINE_JUDGE 70 fclose(stdin); 71 #endif 72 return 0; 73}

