1/* *********************************************** 2Author :111qqz 3Created Time :2016年08月14日 星期日 12时46分56秒 4File Name :code/ccpc2016/1004.cpp 5************************************************ */ 6#include &lt;cstdio&gt; 7#include &lt;cstring&gt; 8#include &lt;iostream&gt; 9#include &lt;algorithm&gt; 10#include &lt;vector&gt; 11#include &lt;queue&gt; 12#include &lt;stack&gt; 13#include &lt;set&gt; 14#include &lt;map&gt; 15#include &lt;string&gt; 16#include &lt;cmath&gt; 17#include &lt;cstdlib&gt; 18#include &lt;deque&gt; 19#include &lt;ctime&gt; 20#define fst first 21#define sec second 22#define lson l,m,rt&lt;&lt;1 23#define rson m+1,r,rt&lt;&lt;1|1 24#define ms(a,x) memset(a,x,sizeof(a)) 25typedef long long LL; 26#define pi pair &lt; int ,int &gt; 27#define MP make_pair 28using namespace std; 29const double eps = 1E-8; 30const int dx4[4]={1,0,0,-1}; 31const int dy4[4]={0,-1,1,0}; 32const int inf = 0x3f3f3f3f; 33const int N=11; 34int n; 35int a[N]; 36int total; 37bool bian[N]; 38bool cmp(int a,int b) 39{ 40 return a&gt;b; 41} 42int main() 43{ 44	#ifndef ONLINE_JUDGE 45	freopen(&#34;code/in.txt&#34;,&#34;r&#34;,stdin); 46 #endif 47	int T; 48	cin&gt;&gt;T; 49	int cas = 0 ; 50	while (T--) 51	{ 52	printf(&#34;Case #%d: &#34;,++cas); 53	scanf(&#34;%d&#34;,&amp;n); 54	ms(bian,false); 55	total = 0 ; 56	for ( int i = 1 ; i &lt;= n ; i++) 57	{ 58	scanf(&#34;%d&#34;,&amp;a[i]); 59	total +=a[i]; 60	} 61	if (n==1) 62	{ 63	if (a[1]&gt;1) 64	puts(&#34;1&#34;); 65	else puts(&#34;0&#34;); 66	continue; 67	} 68	sort(a+1,a+n+1,cmp); 69	int R = total/2; 70	int cur = 0 ; 71	int i = 1; 72	int j = 2; 73	while (cur&lt;R&amp;&amp;i&lt;=n&amp;&amp;j&lt;=n) 74	{ 75//	int x = a[i]; 76//	int y = a[j]; 77	if (a[i]==a[j]) 78	{ 79	cur +=a[i]+a[j]; 80	a[i] = 0; 81	a[j] = 0; 82	i = j+1; 83	j = i+1; 84	} 85	else if (!bian[i]) 86	{ 87	cur +=a[j]+a[j]+1; 88	a[i]-=(a[j]+1); 89	a[j] = 0; 90	j++; 91	if (a[i]&lt;a[j]) swap(a[i],a[j]); 92	else bian[i] = true; 93	} 94	else 95	{ 96	cur +=a[j]+a[j]; 97	a[i]-=a[j]; 98	a[j] = 0; 99	j++; 100	if (a[i]&lt;a[j]) swap(a[i],a[j]); 101	} 102//	cout&lt;&lt;&#34;cur:&#34;&lt;&lt;cur&lt;&lt;endl; 103	} 104	cur = min(cur,R); 105	printf(&#34;%d\n&#34;,cur); 106	} 107 #ifndef ONLINE_JUDGE 108 fclose(stdin); 109 #endif 110 return 0; 111}

