题意：给出一串代表8个方向的数字，求这串序列的一阶差分（the first difference）的字典序最小的表示。
思路：先做个变换，按照题意，第i位的一阶差分 s[i] = ((s[i+1]-s[i])+8)%8;
然后求出最小表示开始的位置。。输出即可。
1/* *********************************************** 2Author :111qqz 3Created Time :2016年08月13日 星期六 02时17分45秒 4File Name :code/poj/4162.cpp 5************************************************ */ 6#include &lt;cstdio&gt; 7#include &lt;cstring&gt; 8#include &lt;iostream&gt; 9#include &lt;algorithm&gt; 10#include &lt;vector&gt; 11#include &lt;queue&gt; 12#include &lt;stack&gt; 13#include &lt;set&gt; 14#include &lt;map&gt; 15#include &lt;string&gt; 16#include &lt;cmath&gt; 17#include &lt;cstdlib&gt; 18#include &lt;deque&gt; 19#include &lt;ctime&gt; 20#define fst first 21#define sec second 22#define lson l,m,rt&lt;&lt;1 23#define rson m+1,r,rt&lt;&lt;1|1 24#define ms(a,x) memset(a,x,sizeof(a)) 25typedef long long LL; 26#define pi pair &lt; int ,int &gt; 27#define MP make_pair 28using namespace std; 29const double eps = 1E-8; 30const int dx4[4]={1,0,0,-1}; 31const int dy4[4]={0,-1,1,0}; 32const int inf = 0x3f3f3f3f; 33const int N=4E5+7; 34int n ; 35char s[N]; 36int minRep(char *s) 37{ 38 int n = strlen(s); 39 int i = 0 ; 40 int j = 1; 41 int k = 0 ; 42 while (i&lt;n&amp;&amp;j&lt;n&amp;&amp;k&lt;n) 43 { 44	int t = s[(i+k)%n]-s[(j+k)%n]; 45	if (t==0) k++; 46	else 47	{ 48	if (t&gt;0) 49	i+=k+1; 50	else j+=k+1; 51	if (i==j) j++; 52	k = 0 ; 53	} 54 } 55 return i&lt;j?i:j; 56} 57int main() 58{ 59	#ifndef ONLINE_JUDGE 60	freopen(&#34;code/in.txt&#34;,&#34;r&#34;,stdin); 61 #endif 62	while (~scanf(&#34;%s&#34;,s)) 63	{ 64	int len = strlen(s); 65	char s0 = s[0]; 66	int p,q; 67	for ( int i = 0 ; i &lt; len-1 ; i++) 68	{ 69	p = s[i]-&#39;0&#39;; 70	q = s[i+1]-&#39;0&#39;; 71	q-=p; 72	if (q&lt;0) q+=8; 73	s[i] = char (q+&#39;0&#39;); 74	} 75	s[len-1] = char(((s0-s[len-1])+8)%8+&#39;0&#39;); 76	int k = minRep(s); 77	int cnt = 1; 78	for (int i = k ; cnt&lt;= len ; i++,cnt++) 79	printf(&#34;%c&#34;,s[i%len]); 80	printf(&#34;\n&#34;); 81	ms(s,0); 82	} 83 #ifndef ONLINE_JUDGE 84 fclose(stdin); 85 #endif 86 return 0; 87}

