i] = toupper(st[i]); 91	} 92//	cout&lt;&lt;&#34;st:&#34;&lt;&lt;st&lt;&lt;endl; 93	ms(ans,-1); 94	while (!stk.empty()) stk.pop(); 95	stk.push(0); 96	for ( int i = 1 ; i &lt; n ; i++) 97	{ 98	while (!stk.empty()&amp;&amp;st[stk.top()]==st[i]&amp;&amp;ok(stk.top(),i)&amp;&amp;i&lt;n) 99	{ 100	stk.pop(); 101	i++; 102	} 103	stk.push(i); 104	} 105	for ( int i = 1 ; i &lt;= n/2 ; i++) 106	{ 107	if (ans[i]==-1) 108	{ 109	puts(&#34;Impossible&#34;); 110	return 0; 111	} 112	} 113	for ( int i = 1 ; i &lt; n/2 ; i++) printf(&#34;%d &#34;,ans[i]); 114	printf(&#34;%d\n&#34;,ans[n/2]); 115 116 #ifndef ONLINE_JUDGE 117 fclose(stdin); 118 #endif 119 return 0; 120}

