cf682C题目链接
题意：给一棵树。。有点权和边权。。。如果一个点v的子树中存在某点u,满足dis(u,v)&gt;a[u]，那么点v就非常sad&hellip;
dis(u,v)表示点u到v的距离。。。a[u]是u的点权。。现在问最少要删除多少个叶子节点才能使得没有点节点感到sad..
思路：dfs一下。。。需要注意的是边权有负数。。。所以类似于区间的最大连续区间和。。。我们也也可以维护在树上的最大连续和。。。只需要如果当前为负就变成0即可。。。
1/* *********************************************** 2Author :111qqz 3Created Time :2016年07月18日 星期一 14时27分58秒 4File Name :code/2016whust/C.cpp 5************************************************ */ 6#include &lt;cstdio&gt; 7#include &lt;cstring&gt; 8#include &lt;iostream&gt; 9#include &lt;algorithm&gt; 10#include &lt;vector&gt; 11#include &lt;queue&gt; 12#include &lt;set&gt; 13#include &lt;map&gt; 14#include &lt;string&gt; 15#include &lt;cmath&gt; 16#include &lt;cstdlib&gt; 17#include &lt;ctime&gt; 18#define fst first 19#define sec second 20#define lson l,m,rt&lt;&lt;1 21#define rson m+1,r,rt&lt;&lt;1|1 22#define ms(a,x) memset(a,x,sizeof(a)) 23typedef long long LL; 24#define pi pair &lt; int ,long long &gt; 25#define MP make_pair 26using namespace std; 27const double eps = 1E-8; 28const int dx4[4]={1,0,0,-1}; 29const int dy4[4]={0,-1,1,0}; 30const int inf = 0x3f3f3f3f; 31const int N=1E5+7; 32LL a[N]; 33LL sum[N]; 34bool vis[N]; 35vector &lt; pi&gt; edge[N]; 36int ans; 37int n; 38void dfs( int u,int pre,LL d) 39{ 40 if (d&gt;a[u]) return ; 41 ans++; 42 int siz = edge[u].size(); 43 for ( int i = 0 ; i &lt; siz ; i++) 44 { 45	int v = edge[u][i].fst; 46	LL w = edge[u][i].sec; 47	if (v==pre) continue; 48	dfs(v,u,w+d&gt;0?w+d:0); 49 } 50} 51int main() 52{ 53	#ifndef ONLINE_JUDGE 54	freopen(&#34;code/in.txt&#34;,&#34;r&#34;,stdin); 55 #endif 56	cin&gt;&gt;n; 57	for ( int i = 1 ; i &lt;= n ; i++) edge[i].clear(); 58	ms(sum,0); 59	for ( int i = 1 ; i &lt;= n ; i++) 60	{ 61	scanf(&#34;%lld&#34;,&amp;a[i]); 62	} 63	for ( int i = 2 ; i &lt;= n ; i++) 64	{ 65	int p; 66	LL c; 67	scanf(&#34;%d%lld&#34;,&amp;p,&amp;c); 68	edge[i].push_back(make_pair(p,c)); 69	edge[p].push_back(make_pair(i,c)); 70	} 71	dfs(1,-1,0); 72	cout&lt;&lt;n-ans&lt;&lt;endl; 73 #ifndef ONLINE_JUDGE 74 fclose(stdin); 75 #endif 76 return 0; 77}

hdu4607题目链接 题意：给出一棵树。。。边权都为1. m个查询。。每个查询给一个k,表示只访问k个点。。。问每次的最小路径和是多少。。。 思路：我们发现。。会使路径和变大的一个不利因素是折返。。也就是访问某景点后。。必须要回去才能继续前进。。这样的距离是2倍。。那为了使得路径和尽可能小。。我们就尽量不要访问这样的点。。。而不是这样的点一定在直径上。。。以及我们还发现。。。不在直径上的点。。 。。不管深度如何（深度的意思是说，与和该点最近的直径上的点的距离），距离的贡献是一样的。。都是2倍。。所以我们可以推出一个公式。。。如果树的直径是d,那么k&lt;=d+1的时候，答案为k-1,否则答案为d+(k-d-1)*2。。。
因为bfs的时候忘记标记起点WA了一发蠢哭。。。。2A
1/* *********************************************** 2Author :111qqz 3Created Time :2016年07月13日 星期三 14时33分29秒 4File Name :code/poj/4607.cpp 5 ************************************************ */ 6 7#include &lt;cstdio&gt; 8#include &lt;cstring&gt; 9#include &lt;iostream&gt; 10#include &lt;algorithm&gt; 11#include &lt;vector&gt; 12#include &lt;queue&gt; 13#include &lt;set&gt; 14#include &lt;map&gt; 15#include &lt;string&gt; 16#include &lt;cmath&gt; 17#include &lt;cstdlib&gt; 18#include &lt;ctime&gt; 19#define fst first 20#define sec second 21#define lson l,m,rt&lt;&lt;1 22#define rson m+1,r,rt&lt;&lt;1|1 23#define ms(a,x) memset(a,x,sizeof(a)) 24typedef long long LL; 25#define pi pair &lt; int ,int &gt; 26#define MP make_pair 27 28using namespace std; 29const double eps = 1E-8; 30const int dx4[4]={1,0,0,-1}; 31const int dy4[4]={0,-1,1,0}; 32const int inf = 0x3f3f3f3f; 33const int N=1E5+7; 34vector&lt; int &gt;edge[N]; 35int n,m; 36int d[N]; 37int lst,beg; 38bool vis[N]; 39 40void bfs( int s) 41{ 42 ms(d,0); 43 ms(vis,false); 44 45 queue&lt;int&gt;q; 46 q.push(s); 47 vis[s] = true; 48 49 while(!q.empty()) 50 { 51	int u = q.front(); 52	q.pop(); 53	//	cout&lt;&lt;&#34;u:&#34;&lt;&lt;u&lt;&lt;endl; 54	int siz = edge[u].size(); 55	for ( int i = 0 ; i &lt;siz ; i++) 56	{ 57	int v = edge[u][i]; 58	if (vis[v]) continue; 59	d[v] = d[u] + 1; 60	vis[v] = true; 61	q.push(v); 62	} 63 } 64} 65int main() 66{ 67#ifndef ONLINE_JUDGE 68 freopen(&#34;code/in.txt&#34;,&#34;r&#34;,stdin); 69#endif 70 int T; 71 cin&gt;&gt;T; 72 while (T--) 73 { 74	scanf(&#34;%d%d&#34;,&amp;n,&amp;m); 75	for ( int i = 1 ; i &lt;= n ; i++) edge[i].clear(); 76	for ( int i = 1 ; i &lt;= n-1 ; i++) 77	{ 78	int u,v; 79	scanf(&#34;%d%d&#34;,&amp;u,&amp;v); 80	edge[u].push_back(v); 81	edge[v].push_back(u); 82	} 83 84	bfs(1); 85	int mx = 0; 86	for ( int i = 1 ; i &lt;= n ; i++) 87	{ 88	if (d[i]&gt;mx) 89	{ 90	mx = d[i]; 91	lst = i; 92	} 93	} 94	//	cout&lt;&lt;endl; 95	bfs(lst); 96	mx = 0 ; 97	for ( int i = 1 ; i &lt;= n ; i++) 98	{ 99	if (d[i]&gt;mx) 100	{ 101	mx = d[i]; 102	beg = i; 103	} 104	} 105	//	cout&lt;&lt;&#34;beg:&#34;&lt;&lt;beg&lt;&lt;&#34; lst:&#34;&lt;&lt;lst&lt;&lt;endl; 106	//	cout&lt;&lt;&#34;mx:&#34;&lt;&lt;mx&lt;&lt;endl; 107	while (m--) 108	{ 109	int x; 110	int ans; 111	scanf(&#34;%d&#34;,&amp;x); 112	if (x&lt;=mx+1) 113	{ 114	ans = x-1; 115	} 116	else 117	{ 118	ans = mx + (x-mx-1)*2; 119	} 120	printf(&#34;%d\n&#34;,ans); 121	} 122 123 } 124 125#ifndef ONLINE_JUDGE 126 fclose(stdin); 127#endif 128 return 0; 129}

URAL1416 题意：次小生成树模板题
思路：用Kruskal求最小生成树，标记用过的边。求次小生成树时，依次枚举用过的边，将其去除后再求最小生成树，得出所有情况下的最小的生成树就是次小的生成树。复杂度o(m2)。。。貌似有其他优化。。。
写的时候。。因为点数是500。。我把边集的数组大小开成了500.。。交了10遍越界才意识到问题在哪里。。。真的是智商掉线啊orz&hellip;
1/* *********************************************** 2Author :111qqz 3Created Time :2016年07月11日 星期一 20时44分28秒 4File Name :code/ural/1416.cpp 5************************************************ */ 6#include &lt;cstdio&gt; 7#include &lt;cstring&gt; 8#include &lt;iostream&gt; 9#include &lt;algorithm&gt; 10#include &lt;vector&gt; 11#include &lt;queue&gt; 12#include &lt;set&gt; 13#include &lt;map&gt; 14#include &lt;string&gt; 15#include &lt;cmath&gt; 16#include &lt;cstdlib&gt; 17#include &lt;ctime&gt; 18#define fst first 19#define sec second 20#define lson l,m,rt&lt;&lt;1 21#define rson m+1,r,rt&lt;&lt;1|1 22#define ms(a,x) memset(a,x,sizeof(a)) 23typedef long long LL; 24#define pi pair &lt; int ,int &gt; 25#define MP make_pair 26using namespace std; 27const double eps = 1E-8; 28const int dx4[4]={1,0,0,-1}; 29const int dy4[4]={0,-1,1,0}; 30const int inf = 0x3f3f3f3f; 31const int N=505; 32int n,m; 33int f[N]; 34int mst; 35int ans; 36int cnt = 0 ; 37vector &lt; pi &gt; e[N*N]; 38bool flag; 39struct Edge 40{ 41 int u,v; 42 int w; 43 int in;//标记边是否在生成树中。 44 bool operator &lt; (Edge b)const 45 { 46	return w&lt;b.w; 47 } 48 void input() 49 { 50	scanf(&#34;%d%d%d&#34;,&amp;u,&amp;v,&amp;w); 51 } 52}E[N*N]; 53void init() 54{ 55 for ( int i = 1 ; i &lt;= n ; i++) f[i] = i; 56 for ( int i = 1 ; i &lt;= n ; i++) e[i].clear(); 57} 58int root ( int x) 59{ 60 // cout&lt;&lt;&#34;x:&#34;&lt;&lt;x&lt;&lt;&#34; f[x]:&#34;&lt;&lt;f[x]&lt;&lt;endl; 61 if (x!=f[x]) f[x] = root (f[x]); 62 return f[x]; 63} 64void merge( int x,int y) 65{ 66 int rx = root (x); 67 int ry = root (y); 68 if (rx==ry) return ; 69 f[rx] = ry; 70 // if (rx&lt;ry) f[ry] = rx; 71 // else f[rx]=ry; 72} 73void kruskal(int k) 74{ 75 for ( int i = 1 ; i &lt;= n ; i++) f[i] = i ; 76 mst = 0 ; 77 cnt = 0; 78 for ( int i = 1; i &lt;= m ; i++) 79 { 80	int u = E[i].u; 81	int v = E[i].v; 82	int w = E[i].w; 83	if (i==k) continue; 84	if (root(u)==root(v)) continue; 85	merge(u,v); 86	cnt++; 87	mst+=w; 88	if (cnt&gt;=n-1) break; 89 } 90 if (cnt&lt;n-1) return ; 91 ans = min(ans,mst); 92} 93int main() 94{ 95	#ifndef ONLINE_JUDGE 96	freopen(&#34;code/in.txt&#34;,&#34;r&#34;,stdin); 97 #endif 98	cin&gt;&gt;n&gt;&gt;m; 99	init(); 100	for ( int i = 1 ; i &lt;= m ; i++) 101	{ 102	E[i].input(); 103	int u = E[i].u; 104	int v = E[i].v; 105	int w = E[i].w; 106 107	e[u].push_back(make_pair(v,w)); 108	e[v].push_back(make_pair(u,w)); 109	} 110	sort(E+1,E+m+1); 111	mst = 0 ; 112	cnt = 0 ; 113	for ( int i = 1 ; i &lt;= m ; i++) 114	{ 115	int u = E[i].u; 116	int v = E[i].v; 117	int w = E[i].w; 118	if (root(u)==root(v)) continue; 119	E[i].in = 1; 120	merge(u,v); 121	cnt++; 122	mst+=w; 123	} 124	if (cnt&lt;n-1) 125	{ 126	puts(&#34;Cost: -1&#34;); 127	puts(&#34;Cost: -1&#34;); 128	return 0; 129	} 130	printf(&#34;Cost: %d\n&#34;,mst); 131	ans = inf; 132	for ( int i = 1 ; i &lt;= m ; i++) 133	{ 134	if (E[i].in==0) continue; 135	// cout&lt;&lt;&#34;hhh?&#34;&lt;&lt;endl; 136	kruskal(i); 137	} 138	if (ans==inf) ans = -1; 139	printf(&#34;Cost: %d\n&#34;,ans); 140 #ifndef ONLINE_JUDGE 141 fclose(stdin); 142 #endif 143 return 0; 144}

