 = x + n; 102	addedge(i,x); 103	} 104	} 105	int ans = hung(); 106	printf(&#34;%d\n&#34;,ans); 107	} 108 109 #ifndef ONLINE_JUDGE 110 fclose(stdin); 111 #endif 112 return 0; 113}

