题意：给出n个数，m,k，问最大的j-i+1,使得【i,j】间的最大值与最小值的差属于[m,k] 思路：rmq+尺取。 2A.
1/* *********************************************** 2Author :111qqz 3Created Time :2016年05月19日 星期四 16时52分03秒 4File Name :code/hdu/3530.cpp 5************************************************ */ 6 7#include &lt;cstdio&gt; 8#include &lt;cstring&gt; 9#include &lt;iostream&gt; 10#include &lt;algorithm&gt; 11#include &lt;vector&gt; 12#include &lt;queue&gt; 13#include &lt;set&gt; 14#include &lt;map&gt; 15#include &lt;string&gt; 16#include &lt;cmath&gt; 17#include &lt;cstdlib&gt; 18#include &lt;ctime&gt; 19#define fst first 20#define sec second 21#define lson l,m,rt&lt;&lt;1 22#define rson m+1,r,rt&lt;&lt;1|1 23#define ms(a,x) memset(a,x,sizeof(a)) 24typedef long long LL; 25#define pi pair &lt; int ,int &gt; 26#define MP make_pair 27 28using namespace std; 29const double eps = 1E-8; 30const int dx4[4]={1,0,0,-1}; 31const int dy4[4]={0,-1,1,0}; 32const int inf = 0x3f3f3f3f; 33const int N=1E5+7; 34int n; 35int a[N]; 36int dp[N][20],dp2[N][20]; 37int m,k; 38 39void rmq_init() 40{ 41 for ( int i = 1 ; i &lt;= n ; i ++) 42	dp[i][0] = dp2[i][0] = a[i]; 43 44 for ( int j = 1 ; (1&lt;&lt;j) &lt;= n ; j++) 45	for ( int i = 1 ; i + (1&lt;&lt;j) -1 &lt;= n ; i++) 46	{ 47	dp[i][j] = max(dp[i][j-1],dp[i+(1&lt;&lt;(j-1))][j-1]); 48	dp2[i][j]=min(dp2[i][j-1],dp2[i+(1&lt;&lt;(j-1))][j-1]); 49	} 50} 51 52int rmq( int l,int r) 53{ 54 int k = 0 ; 55 while (1&lt;&lt;(k+1)&lt;=r-l+1) k++; 56 int mx = max(dp[l][k],dp[r-(1&lt;&lt;k)+1][k]); 57 int mn = min(dp2[l][k],dp2[r-(1&lt;&lt;k)+1][k]); 58 59 return mx-mn; 60} 61 62int ruler() 63{ 64 int head = 1; 65 int tail = 1; 66 int res = -1 ; 67 while (tail&lt;=n) 68 { 69	int cur = rmq(head,tail); 70	while (head&lt;tail&amp;&amp;rmq(head,tail)&gt;k) head++; 71	while (tail&lt;n&amp;&amp;rmq(head,tail)&lt;m) tail++; 72	//if (tail&gt;n) break; 73	cur = rmq(head,tail); 74	if (cur&gt;=m&amp;&amp;cur&lt;=k) 75	{ 76	res = max(res,tail-head); 77	} 78//	cout&lt;&lt;&#34;head:&#34;&lt;&lt;head&lt;&lt;&#34; tail:&#34;&lt;&lt;tail&lt;&lt;&#34; cur:&#34;&lt;&lt;cur&lt;&lt;&#34; res:&#34;&lt;&lt;res&lt;&lt;endl; 79	tail++; 80 81 } 82 return res+1; 83} 84int main() 85{ 86	#ifndef ONLINE_JUDGE 87	freopen(&#34;code/in.txt&#34;,&#34;r&#34;,stdin); 88 #endif 89 90	while (scanf(&#34;%d %d %d&#34;,&amp;n,&amp;m,&amp;k)!=EOF) 91	{ 92	ms(dp,0); 93	for ( int i = 1 ; i &lt;= n ; i++) scanf(&#34;%d&#34;,&amp;a[i]); 94	if (m&gt;k) 95	{ 96	puts(&#34;0&#34;); 97	continue; 98	} 99	rmq_init(); 100	printf(&#34;%d\n&#34;,ruler()); 101	} 102 103 104 105 #ifndef ONLINE_JUDGE 106 fclose(stdin); 107 #endif 108 return 0; 109}

