1/* *********************************************** 2Author :111qqz 3Created Time :2016年05月19日 星期四 15时44分12秒 4File Name :code/poj/1470.cpp 5************************************************ */ 6 7#include &lt;cstdio&gt; 8#include &lt;cstring&gt; 9#include &lt;iostream&gt; 10#include &lt;algorithm&gt; 11#include &lt;vector&gt; 12#include &lt;queue&gt; 13#include &lt;set&gt; 14#include &lt;map&gt; 15#include &lt;string&gt; 16#include &lt;cmath&gt; 17#include &lt;cstdlib&gt; 18#include &lt;ctime&gt; 19#define fst first 20#define sec second 21#define lson l,m,rt&lt;&lt;1 22#define rson m+1,r,rt&lt;&lt;1|1 23#define ms(a,x) memset(a,x,sizeof(a)) 24typedef long long LL; 25#define pi pair &lt; int ,int &gt; 26#define MP make_pair 27 28using namespace std; 29const double eps = 1E-8; 30const int dx4[4]={1,0,0,-1}; 31const int dy4[4]={0,-1,1,0}; 32const int inf = 0x3f3f3f3f; 33const int N=905; 34int n; 35vector &lt;int&gt; edge[N]; 36int in[N]; 37int E[2*N],R[2*N]; 38int depth[2*N]; 39int p; 40int dp[2*N][12]; 41int cnt[N]; 42void dfs( int u,int dep) 43{ 44 p++; 45 E[p] = u ; 46 depth[p] = dep; 47 R[u] = p; 48 int siz = edge[u].size(); 49 for ( int i = 0 ; i &lt; siz ; i ++) 50 { 51	int v = edge[u][i]; 52 53	dfs(v,dep+1); 54	p++; 55	E[p] = u; 56	depth[p] = dep; 57 } 58} 59 60int _min( int l,int r) 61{ 62 if (depth[l]&lt;depth[r]) return l; 63 return r; 64} 65void rmq_init() 66{ 67 for ( int i = 1 ; i &lt;=2*n+2 ; i++) dp[i][0] = i; 68 69 for ( int j = 1 ; (1&lt;&lt;j) &lt;= 2*n+2 ; j++) 70	for ( int i = 1 ; i + (1&lt;&lt;j)-1 &lt;= 2*n+2 ; i++) 71	dp[i][j] = _min(dp[i][j-1],dp[i+(1&lt;&lt;(j-1))][j-1]); 72} 73 74int rmq_min( int l,int r) 75{ 76 if (l&gt;r) swap(l,r); 77 int k = 0; 78 while (1&lt;&lt;(k+1) &lt;= r-l+1) k++; 79 return _min(dp[l][k],dp[r-(1&lt;&lt;k)+1][k]); 80} 81int main() 82{ 83	#ifndef ONLINE_JUDGE 84	freopen(&#34;code/in.txt&#34;,&#34;r&#34;,stdin); 85 #endif 86 87	while (scanf(&#34;%d&#34;,&amp;n)!=EOF) 88	{ 89	ms(in,0); 90	for ( int i = 1 ; i &lt;= n ; i++