题目链接 题意：给出n个时间的开始和截止时间，保证没有两个时间的开始或者截止时间相同，问有多少个时间被包含在其他事件中。即aj &lt; ai and bi &lt; bj.
思路：没有两个事件的时间相同很关键。 那么我们可以直接按照开始时间为关键字排序，然后结束时间取之前发生了的（可能还没发生完）时间的结束时间的最大值即可。
1/* *********************************************** 2Author :111qqz 3Created Time :2016年03月31日 星期四 13时23分21秒 4File Name :code/cf/problem/137C.cpp 5************************************************ */ 6 7#include &lt;cstdio&gt; 8#include &lt;cstring&gt; 9#include &lt;iostream&gt; 10#include &lt;algorithm&gt; 11#include &lt;vector&gt; 12#include &lt;queue&gt; 13#include &lt;set&gt; 14#include &lt;map&gt; 15#include &lt;string&gt; 16#include &lt;cmath&gt; 17#include &lt;cstdlib&gt; 18#include &lt;ctime&gt; 19#define fst first 20#define sec second 21#define lson l,m,rt&lt;&lt;1 22#define rson m+1,r,rt&lt;&lt;1|1 23#define ms(a,x) memset(a,x,sizeof(a)) 24typedef long long LL; 25#define pi pair &lt; int ,int &gt; 26#define MP make_pair 27 28using namespace std; 29const double eps = 1E-8; 30const int dx4[4]={1,0,0,-1}; 31const int dy4[4]={0,-1,1,0}; 32const int inf = 0x3f3f3f3f; 33const int N=1E5+7; 34int n; 35pi a[N]; 36int main() 37{ 38	#ifndef ONLINE_JUDGE 39	freopen(&#34;code/in.txt&#34;,&#34;r&#34;,stdin); 40 #endif 41	cin&gt;&gt;n; 42	for ( int i = 1; i &lt;= n ; i++) cin&gt;&gt;a[i].fst&gt;&gt;a[i].sec; 43 44	sort(a+1,a+n+1); 45 46	int r = a[1].sec; 47	int ans = 0 ; 48	for ( int i = 2 ; i &lt;= n ; i++) 49	{ 50	if (a[i].sec&lt;r) ans++; 51	r = max(r,a[i].sec); 52	} 53 54	cout&lt;&lt;ans&lt;&lt;endl; 55 56 #ifndef ONLINE_JUDGE 57 fclose(stdin); 58 #endif 59 return 0; 60}

题目链接 题意：给出n个点，m条边，定义一条路径的价值为【路径长度*(路径终点的度)】，求最大价值。 思路：一月份的时候写过一个回溯。。。TLE22了。。。其实也能猜到是dp..但是无奈不会写。然而其实真的不难== 我们枚举路径的终点，dp[i]表示以点i为终点能得到的最长路径长度。
转移方程：dp[i] = max(dp[i],dp[edge[i][j]]+1);
含义是与i点相连的j点是否要将i点加在以j点为路径末尾的路径的终点，使i点成为新的路径终点。
具体看代码
1/* *********************************************** 2Author :111qqz 3Created Time :2016年01月08日 星期五 21时55分26秒 4File Name :code/cf/#338/B.cpp 5************************************************ */ 6 7#include &lt;cstdio&gt; 8#include &lt;cstring&gt; 9#include &lt;iostream&gt; 10#include &lt;algorithm&gt; 11#include &lt;vector&gt; 12#include &lt;queue&gt; 13#include &lt;set&gt; 14#include &lt;map&gt; 15#include &lt;string&gt; 16#include &lt;cmath&gt; 17#include &lt;cstdlib&gt; 18#include &lt;ctime&gt; 19#define fst first 20#define sec second 21#define lson l,m,rt&lt;&lt;1 22#define rson m+1,r,rt&lt;&lt;1|1 23#define ms(a,x) memset(a,x,sizeof(a)) 24typedef long long LL; 25#define pi pair &lt; int ,int &gt; 26#define MP make_pair 27 28using namespace std; 29const double eps = 1E-8; 30const int dx4[4]={1,0,0,-1}; 31const int dy4[4]={0,-1,1,0}; 32const int inf = 0x3f3f3f3f; 33const int N=2E5+7; 34int n,m; 35vector&lt;int&gt;edge[N]; 36LL ans; 37LL cur; 38LL dp[N]; 39 40 41int main() 42{ 43	#ifndef ONLINE_JUDGE 44	freopen(&#34;code/in.txt&#34;,&#34;r&#34;,stdin); 45 #endif 46	cin&gt;&gt;n&gt;&gt;m; 47	for ( int i = 0 ; i &lt; m ; i ++) 48	{ 49	int x,y; 50	scanf(&#34;%d %d&#34;,&amp;x,&amp;y); 51	edge[x].push_back(y); 52	edge[y].push_back(x); 53	} 54 55	for ( int i = 1 ; i &lt;= n ; i++) 56	{ 57	dp[i] = 1; 58	for (int j = 0 ; j &lt; int(edge[i].size()) ; j++) 59	{ 60	int v = edge[i][j]; 61	dp[i] = max(dp[i],dp[v]+1); 62	} 63	ans = max(ans,LL(edge[i].size())*dp[i]); 64	} 65	cout&lt;&lt;ans&lt;&lt;endl; 66 67 #ifndef ONLINE_JUDGE 68 fclose(stdin); 69 #endif 70 return 0; 71}

题目链接 题意：n个点，m（m&lt;n/2）条不能走的边，问最少连多少条边，使得任何两个点之间的距离最多为2. 输出最少的边数和连接的哪些边。 思路： **数据范围很关键。**数据范围很关键。数据范围很关键。
因为m&lt;n/2,每条禁止的边最多禁止两个点，所以禁止的点数&lt;n..那么至少有一个点是和可以和其他所有点相连的。。于是把其他所有点和该点相连即可。
1/* *********************************************** 2Author :111qqz 3Created Time :2016年03月19日 星期六 10时39分40秒 4File Name :code/cf/problem/330B.cpp 5************************************************ */ 6 7#include &lt;cstdio&gt; 8#include &lt;cstring&gt; 9#include &lt;iostream&gt; 10#include &lt;algorithm&gt; 11#include &lt;vector&gt; 12#include &lt;queue&gt; 13#include &lt;set&gt; 14#include &lt;map&gt; 15#include &lt;string&gt; 16#include &lt;cmath&gt; 17#include &lt;cstdlib&gt; 18#include &lt;ctime&gt; 19#define fst first 20#define sec second 21#define lson l,m,rt&lt;&lt;1 22#define rson m+1,r,rt&lt;&lt;1|1 23#define ms(a,x) memset(a,x,sizeof(a)) 24typedef long long LL; 25#define pi pair &lt; int ,int &gt; 26#define MP make_pair 27 28using namespace std; 29const double eps = 1E-8; 30const int dx4[4]={1,0,0,-1}; 31const int dy4[4]={0,-1,1,0}; 32const int inf = 0x3f3f3f3f; 33const int N=1E3+7; 34int cnt[N]; 35int n,m; 36int main() 37{ 38	#ifndef ONLINE_JUDGE 39	freopen(&#34;code/in.txt&#34;,&#34;r&#34;,stdin); 40 #endif 41 42	ms(cnt,0); 43	cin&gt;&gt;n&gt;&gt;m; 44	for ( int i = 1 ; i &lt;= m ; i++) //因为m&lt;n/2...一条m限制两个点不能相连。。最多限制2*m&lt;n个。。。 45	{	//所以至少有一个点不受任何限制。。把其他的所有点连到这个点上即可。 46	int u,v; //此时得到一个 star graph. 47	cin&gt;&gt;u&gt;&gt;v; 48	cnt[v]++; 49	cnt[u]++; 50	} 51 52	int p; 53	for ( int i = 1 ; i &lt;= n ; i++) 54	{ 55	if (cnt[i] == 0) 56	{ 57	p = i ; 58	break; 59	} 60	} 61 62	cout&lt;&lt;n-1&lt;&lt;endl; 63	for ( int i = 1; i &lt;= n ; i++) 64	{ 65	if (i==p) continue; 66	cout&lt;&lt;p&lt;&lt;&#34; &#34;&lt;&lt;i&lt;&lt;endl; 67	} 68 69 70 71 72 #ifndef ONLINE_JUDGE 73 fclose(stdin); 74 #endif 75 return 0; 76}

题目链接 题意：给出n和k,给出一个长度为n的字符串表示房间的占用情况（0表示没占用，1表示已占用），从n个房间中找出k+1个，使得k+1中的k个距离k+1个中的1个的距离和最小。
思路：只需要考虑没被占用的位置。所以用pos[]数组记录0的位置。 找到第一个能住下的位置后向前平移即可。
1/* *********************************************** 2Author :111qqz 3Created Time :2016年03月19日 星期六 00时21分28秒 4File Name :code/cf/croc2016/C.cpp 5************************************************ */ 6 7#include &lt;cstdio&gt; 8#include &lt;cstring&gt; 9#include &lt;iostream&gt; 10#include &lt;algorithm&gt; 11#include &lt;vector&gt; 12#include &lt;queue&gt; 13#include &lt;set&gt; 14#include &lt;map&gt; 15#include &lt;string&gt; 16#include &lt;cmath&gt; 17#include &lt;cstdlib&gt; 18#include &lt;ctime&gt; 19#define fst first 20#define sec second 21#define lson l,m,rt&lt;&lt;1 22#define rson m+1,r,rt&lt;&lt;1|1 23#define ms(a,x) memset(a,x,sizeof(a)) 24typedef long long LL; 25#define pi pair &lt; int ,int &gt; 26#define MP make_pair 27 28using namespace std; 29const double eps = 1E-8; 30const int dx4[4]={1,0,0,-1}; 31const int dy4[4]={0,-1,1,0}; 32const int inf = 0x3f3f3f3f; 33const int N=1E5+7; 34int ban[N]; 35int k,n; 36int sum[N]; 37int pos0[N]; 38string st; 39 40int dis(int x,int l,int r) 41{ 42 return max(pos0[x]-pos0[l],pos0[r]-pos0[x]); 43} 44int main() 45{ 46	#ifndef ONLINE_JUDGE 47	freopen(&#34;code/in.txt&#34;,&#34;r&#34;,stdin); 48 #endif 49	cin&gt;&gt;n&gt;&gt;k; 50	cin&gt;&gt;st; 51	ms(ban,0); 52	ms(pos0,0); 53	k++; 54	int len = st.length(); 55	int cnt0 = 0; 56	for ( int i = 0 ; i &lt; len ; i++) 57	{ 58	if (st[i]==&#39;0&#39;) 59	{ 60	ban[i+1] = 0; 61	cnt0++; 62	pos0[cnt0] = i ; 63	} 64	else 65	{ 66	ban[i+1] = 1; 67	} 68	} 69 70	sum[0] = 0 ; 71 72	for ( int i = 1 ; i &lt;= n ; i++) 73	{ 74	sum[i] = sum[i-1] + ban[i]; 75	} 76	int ans = inf; 77	int l = 1 ; int r = k; 78	int mid = 0; 79	for ( int i = 1 ; i &lt;= r ; i++) 80	{ 81	if (dis(i,l,r)&lt;dis(mid,l,r)) 82	{ 83	mid = i; 84	} 85	} 86 87	ans = dis(mid,l,r); 88	for ( ; r &lt;= cnt0 ; r++,l++) 89	{ 90	while (dis(mid+1,l,r)&lt;dis(mid,l,r)) mid++; 91	ans = min(ans,dis(mid,l,r)); 92	} 93	cout&lt;&lt;ans&lt;&lt;endl; 94 95 96 97 98 99 #ifndef ONLINE_JUDGE 100 fclose(stdin); 101 #endif 102 return 0; 103}

题目链接 题意：两个手柄？ 初始的电量给出，只有一个充电器，每经过一秒，充着电的手柄电量增加1，没有充电的手柄电量减少2，允许电量充到0以上，当有电量为0的时候，或者当某一分钟开始的时候有手柄电量为1，游戏立即结束。问最多能玩多少时间游戏。
思路：贪心。。每次给电量少的充电。 坑点在于当某一时刻有手柄电量为1，那么游戏在进行这一分钟之前就结束。
1/* *********************************************** 2Author :111qqz 3Created Time :2016年03月07日 星期一 17时06分41秒 4File Name :code/cf/#345/A.cpp 5************************************************ */ 6 7#include &lt;cstdio&gt; 8#include &lt;cstring&gt; 9#include &lt;iostream&gt; 10#include &lt;algorithm&gt; 11#include &lt;vector&gt; 12#include &lt;queue&gt; 13#include &lt;set&gt; 14#include &lt;map&gt; 15#include &lt;string&gt; 16#include &lt;cmath&gt; 17#include &lt;cstdlib&gt; 18#include &lt;ctime&gt; 19#define fst first 20#define sec second 21#define lson l,m,rt&lt;&lt;1 22#define rson m+1,r,rt&lt;&lt;1|1 23#define ms(a,x) memset(a,x,sizeof(a)) 24typedef long long LL; 25#define pi pair &lt; int ,int &gt; 26#define MP make_pair 27 28using namespace std; 29const double eps = 1E-8; 30const int dx4[4]={1,0,0,-1}; 31const int dy4[4]={0,-1,1,0}; 32const int inf = 0x3f3f3f3f; 33int a,b; 34int main() 35{ 36	#ifndef ONLINE_JUDGE 37	freopen(&#34;code/in.txt&#34;,&#34;r&#34;,stdin); 38 #endif 39	cin&gt;&gt;a&gt;&gt;b; 40	int cnt = 0 ; 41	while (1) 42	{ 43	if (a&gt;b) 44	{ 45	a-=2; 46	if (a&lt;0) break; 47	b++; 48	} 49	else 50	{ 51	a++; 52	b-=2; 53	if (b&lt;0) break; 54	} 55	cnt++; 56	// if (a==1&amp;&amp;b==1) break; 57	if (a&lt;=0||b&lt;=0) break; 58	} 59	cout&lt;&lt;cnt&lt;&lt;endl; 60 61 #ifndef ONLINE_JUDGE 62 fclose(stdin); 63 #endif 64 return 0; 65}

http://acm.hdu.edu.cn/showproblem.php?pid=5630 题意：nm的棋盘，相邻格子的颜色相反，每次可以翻转一个任意大小矩形的格子，问最少需要翻转多少次使得棋盘的nm个格子颜色相同。（翻转的意思是颜色反色）
