1/* *********************************************** 2Author :111qqz 3Created Time :2016年02月25日 星期四 21时53分43秒 4File Name :code/hdu/1028.cpp 5************************************************ */ 6 7#include &lt;cstdio&gt; 8#include &lt;cstring&gt; 9#include &lt;iostream&gt; 10#include &lt;algorithm&gt; 11#include &lt;vector&gt; 12#include &lt;queue&gt; 13#include &lt;set&gt; 14#include &lt;map&gt; 15#include &lt;string&gt; 16#include &lt;cmath&gt; 17#include &lt;cstdlib&gt; 18#include &lt;ctime&gt; 19#define fst first 20#define sec second 21#define lson l,m,rt&lt;&lt;1 22#define rson m+1,r,rt&lt;&lt;1|1 23#define ms(a,x) memset(a,x,sizeof(a)) 24typedef long long LL; 25#define pi pair &lt; int ,int &gt; 26#define MP make_pair 27 28using namespace std; 29const double eps = 1E-8; 30const int dx4[4]={1,0,0,-1}; 31const int dy4[4]={0,-1,1,0}; 32const int inf = 0x3f3f3f3f; 33const int N=125; 34int n; 35int a[N],tmp[N]; //a[i]表示每两个表达式运算时候的前一个表达式的x^i的系数，以及最后的表达式的x^i的系数 36	//tmp[i]是每次运算临时存储指数用 37int main() 38{ 39	#ifndef ONLINE_JUDGE 40	freopen(&#34;code/in.txt&#34;,&#34;r&#34;,stdin); 41 #endif 42 43	while (~scanf(&#34;%d&#34;,&amp;n)) //第i个表达式的样子为：(1+x^i,+x^(2*i),....) 表示有一个i,两个i...... 44	{ 45	for ( int i = 0 ; i &lt;= n ; i++) //所以指数都非负，所以最多有n个表达式对答案有贡献。 46	{ 47	a[i] = 1; 48	tmp[i] = 0 ; 49	} 50//每次只考虑两个表达式的运算，把运算结果放在第一个表达式里。 51	for ( int i = 2 ; i &lt;= n ; i++) //i表示第i个表达式 52	{ 53	for ( int j = 0 ; j &lt;= n ; j++) //j表示第一个表达式的第j个变量 54	{ 55	for ( int k = 0 ; k+j&lt;= n ; k+=i) //k表示第i个表达式的指数，0,i,2*i,3*i... 56	{ 57	tmp[j+k] += a[j]; 58	} 59	} 60 61	for ( int j = 0 ; j &lt;= n ; j++) 62	{ 63	a[j] = tmp[j]; 64	tmp[j] = 0 ; 65	} 66	} 67 68	// for ( int i = 0 ; i &lt;= n ; i++) cout&lt;&lt;&#34;i:&#34;&lt;&lt;i&lt;&lt;&#34; &#34;&lt;&lt;a[i]&lt;&lt;endl; 69 70	printf(&#34;%d\n&#34;,a[n]); 71	} 72 73 #ifndef ONLINE_JUDGE 74 fclose(stdin); 75 #endif 76 return 0; 77}

