题意：中文题目，简单来说就是求某一区间内的逆序对数。
思路：逆序对数想到树状数组。不过写莫队转移的时候没弄明白。。。。大概是树状数组理解的还不够透彻。。。需要复习一下了。。。
还有这题没给数据范围但是需要离散化。。。不然会re&hellip;
1/* *********************************************** 2Author :111qqz 3Created Time :2016年02月17日 星期三 20时18分51秒 4File Name :code/bzoj/3289.cpp 5************************************************ */ 6 7#include &lt;cstdio&gt; 8#include &lt;cstring&gt; 9#include &lt;iostream&gt; 10#include &lt;algorithm&gt; 11#include &lt;vector&gt; 12#include &lt;queue&gt; 13#include &lt;set&gt; 14#include &lt;map&gt; 15#include &lt;string&gt; 16#include &lt;cmath&gt; 17#include &lt;cstdlib&gt; 18#include &lt;ctime&gt; 19#define fst first 20#define sec second 21#define lson l,m,rt&lt;&lt;1 22#define rson m+1,r,rt&lt;&lt;1|1 23#define ms(a,x) memset(a,x,sizeof(a)) 24typedef long long LL; 25#define pi pair &lt; int ,int &gt; 26#define MP make_pair 27 28using namespace std; 29const double eps = 1E-8; 30const int dx4[4]={1,0,0,-1}; 31const int dy4[4]={0,-1,1,0}; 32const int inf = 0x3f3f3f3f; 33const int N=5E4+11; 34int n,m; 35int a[N],b[N]; 36int pos[N]; 37LL c[N]; 38LL ans[N]; 39LL sum; 40struct node 41{ 42 int l,r; 43 int id; 44 45 bool operator &lt; (node b)const 46 { 47	if (pos[l]==pos[b.l]) return r&lt;b.r; 48	return pos[l]&lt;pos[b.l]; 49 } 50}q[N]; 51 52int lowbit( int x) 53{ 54 return x&amp;(-x); 55} 56 57void update ( int x,int delta) 58{ 59 for ( int i = x ;i &lt;=n ; i+=lowbit(i)) 60 { 61	c[i] +=delta; 62 } 63} 64 65LL Sum( int x) 66{ 67 LL res = 0LL ; 68 for ( int i = x; i &gt;=1 ; i-=lowbit(i)) 69 { 70	res += 1LL*c[i]; 71 } 72 return res; 73} 74 75 76int main() 77{ 78	#ifndef ONLINE_JUDGE 79	freopen(&#34;code/in.txt&#34;,&#34;r&#34;,stdin); 80 #endif 81 82	scanf(&#34;%d&#34;,&amp;n); 83	int siz = 223; //sqrt(50000); 84 for ( int i = 1 ;i &lt;= n ; i++) 85 { 86	scanf(&#34;%d&#34;,&amp;a[i]); 87	pos[i] = (i-1)/siz; 88	b[i] = a[i]; 89	} 90	sort(b+1,b+n+1); 91	int t = unique(b+1,b+n+1)-b-1; 92	for ( int i = 1 ; i &lt;= n ; i++) a[i] = lower_bound(b+1,b+t+1,a[i])-b; 93 94//	for ( int i = 1 ;i &lt;= n ; i++) cout&lt;&lt;&#34;a[i]:&#34;&lt;&lt;a[i]&lt;&lt;endl; 95	scanf(&#34;%d&#34;,&amp;m); 96	for ( int i = 1 ;i &lt;= m; i++) 97	{ 98	scanf(&#34;%d %d&#34;,&amp;q[i].l,&amp;q[i].r); 99	q[i].id = i ; 100	} 101 102	sort(q+1,q+m+1); 103 104	int pl=1,pr=0; 105	int l,r,id; 106	sum = 0 ; 107	ms(c,0); 108	ms(ans,0LL); 109	for ( int i = 1; i &lt;= m; i++) 110	{ 111	l = q[i].l; 112	r = q[i].r; 113	id = q[i].id; 114	while (pr&lt;r) 115	{ 116	update(a[++pr],1); 117	sum +=pr-pl-Sum(a[pr]-1); 118	} 119	while (pr&gt;r) 120	{ 121	sum -= pr-pl-Sum(a[pr]-1); 122	update(a[pr--],-1); 123	} 124	while (pl&lt;l) 125	{ 126	sum -= Sum(a[pl]-1); 127	update(a[pl++],-1); 128	} 129	while (pl&gt;l) 130	{ 131	update(a[--pl],1); 132	sum +=Sum(a[pl]-1); 133	} 134 135	// cout&lt;&lt;&#34;sum:&#34;&lt;&lt;sum&lt;&lt;endl; 136 137	ans[id] = sum; 138	} 139	for ( int i = 1 ; i &lt;= m ; i++) printf(&#34;%lld\n&#34;,ans[i]); 140 #ifndef ONLINE_JUDGE 141 fclose(stdin); 142 #endif 143 return 0; 144}

http://acm.zju.edu.cn/onlinejudge/showProblem.do?problemCode=3693 题意： n+2个人取吃饭，每人w元，每k个人可以少付一个人的钱，问最后两个教练每人要付多少钱。
思路：贪心。坑点在读题。。选手n个人，不要忘记两个教练，以及，钱数是两个教练平分。
1/* *********************************************** 2Author :111qqz 3Created Time :2016年02月18日 星期四 15时16分59秒 4File Name :code/zoj/3693.cpp 5************************************************ */ 6 7#include &lt;cstdio&gt; 8#include &lt;cstring&gt; 9#include &lt;iostream&gt; 10#include &lt;algorithm&gt; 11#include &lt;vector&gt; 12#include &lt;queue&gt; 13#include &lt;set&gt; 14#include &lt;map&gt; 15#include &lt;string&gt; 16#include &lt;cmath&gt; 17#include &lt;cstdlib&gt; 18#include &lt;ctime&gt; 19#define fst first 20#define sec second 21#define lson l,m,rt&lt;&lt;1 22#define rson m+1,r,rt&lt;&lt;1|1 23#define ms(a,x) memset(a,x,sizeof(a)) 24typedef long long LL; 25#define pi pair &lt; int ,int &gt; 26#define MP make_pair 27 28using namespace std; 29const double eps = 1E-8; 30const int dx4[4]={1,0,0,-1}; 31const int dy4[4]={0,-1,1,0}; 32const int inf = 0x3f3f3f3f; 33int n,k; 34double ans,w; 35int dblcmp(double d) 36{ 37 return d&lt;-eps?-1:d&gt;eps; 38} 39int main() 40{ 41	#ifndef ONLINE_JUDGE 42	freopen(&#34;code/in.txt&#34;,&#34;r&#34;,stdin); 43 #endif 44 45	while (~scanf(&#34;%d %lf %d&#34;,&amp;n,&amp;w,&amp;k)) //认真读题 46	{ 47	if (dblcmp(w)==0) 48	{ 49	puts(&#34;0.00&#34;); 50	continue; 51	} 52	n = n + 2; 53	n = n-n/k; 54	ans = n*w; 55	ans = ans * 50; 56	printf(&#34;%.2f\n&#34;,int(ans+0.5)*1.0/100); 57	} 58 59 #ifndef ONLINE_JUDGE 60 fclose(stdin); 61 #endif 62 return 0; 63}

http://acm.hdu.edu.cn/showproblem.php?pid=5145 题意：有n个女孩，编号1..n,第i个女孩在第a[i]个教室,m次访问，每次访问编号[L,R]的女孩，处于同一个教室的女孩一次只能访问一个，问有多少种访问方案。两个不同的方案当且仅当访问的顺序有所不同。
思路：正好刚刚听完学堂在线上的组合数学的那一节，讲到有重复元素的不重复排列的个数的计算方法：可以先将所有元素看成不重复，再除以每个元素的重复度的阶乘（重复度定义为每个元素个数）。 # 增加一个元素的影响是，乘一个增加的长度，并且除以该元素的重复度（因为每增加一个元素就要除以以此重复度，那么当同一元素c增加到第i次时，除以的就是i的阶乘），减少一个元素的影响正相反。 两种改变都可以O(1)实现，因此可以上莫队。 # 之前要预处理下逆元。
1/* *********************************************** 2Author :111qqz 3Created Time :2016年02月17日 星期三 14时20分01秒 4File Name :code/hdu/5145.cpp 5************************************************ */ 6 7#include &lt;cstdio&gt; 8#include &lt;cstring&gt; 9#include &lt;iostream&gt; 10#include &lt;algorithm&gt; 11#include &lt;vector&gt; 12#include &lt;queue&gt; 13#include &lt;set&gt; 14#include &lt;map&gt; 15#include &lt;string&gt; 16#include &lt;cmath&gt; 17#include &lt;cstdlib&gt; 18#include &lt;ctime&gt; 19#define fst first 20#define sec second 21#define lson l,m,rt&lt;&lt;1 22#define rson m+1,r,rt&lt;&lt;1|1 23#define ms(a,x) memset(a,x,sizeof(a)) 24typedef long long LL; 25#define pi pair &lt; int ,int &gt; 26#define MP make_pair 27 28using namespace std; 29const double eps = 1E-8; 30const int dx4[4]={1,0,0,-1}; 31const int dy4[4]={0,-1,1,0}; 32const int inf = 0x3f3f3f3f; 33const int N=3E5+7; 34const int MOD =1E9+7; 35int n,m; 36int a[N]; 37int pos[N]; 38LL ny[N]; 39LL p; 40LL num; 41int ans[N]; 42int cnt[N]; 43 44struct node 45{ 46 int l,r; 47 int id; 48 49 bool operator &lt;(node b)const 50 { 51	if (pos[l]==pos[b.l]) return r&lt;b.r; 52	return pos[l]&lt;pos[b.l]; 53 } 54}q[N]; 55 56LL ksm(LL a,LL b) 57{ 58 LL res = 1LL; 59 while (b) 60 { 61	if (b&amp;1) 62	res =(res*a)%MOD; 63	b = b&gt;&gt;1; 64	a = (a*a)%MOD; 65 } 66 return res; 67 68} 69 70 71void update(int x,int d) 72{ 73 if (d&gt;0) 74 { 75	num++; 76	p = (p*num)%MOD; 77	cnt[a[x]]++; 78//	if (cnt[a[x]]&gt;3E4) return; 79	p = (p*ny[cnt[a[x]]])%MOD; 80 } 81 else 82 { 83 84	p = (p*cnt[a[x]])%MOD; 85	cnt[a[x]]--; 86//	if (num&gt;3E4||num&lt;0) return; 87	p = (p*ny[num])%MOD; 88	num--; 89 } 90} 91 92 93 94void getny() //预处理逆元 95{ 96 ms(ny,0); 97 for ( int i = 1 ; i &lt;= 30005 ; i++) 98 { 99	ny[i]=ksm(LL(i),MOD-2); 100 } 101} 102int main() 103{ 104	#ifndef ONLINE_JUDGE 105	freopen(&#34;code/in.txt&#34;,&#34;r&#34;,stdin); 106 #endif 107 108	getny(); 109	int T; 110	cin&gt;&gt;T; 111	while (T--) 112	{ 113 114	scanf(&#34;%d %d&#34;,&amp;n,&amp;m); 115	ms(cnt,0); 116	p = 1LL; 117	num = 0LL; 118	ms(ans,0); 119 120	int siz = 173; //sqrt(30000); 121	for ( int i = 1 ; i &lt;= n ; i++) 122	{ 123	scanf(&#34;%d&#34;,&amp;a[i]); 124	pos[i] = (i-1)/siz; 125	} 126	for ( int i = 1 ; i &lt;= m ; i ++) 127	{ 128	scanf(&#34;%d %d&#34;,&amp;q[i].l,&amp;q[i].r); 129	q[i].id = i ; 130	} 131 132	sort(q+1,q+m+1); 133//	cout&lt;&lt;&#34;ok2&lt;&#34;&lt;&lt;endl; 134	int pl = 1; 135	int pr = 0 ; 136	int id,l,r; 137 138	for ( int i = 1 ; i &lt;= m ; i++) 139	{ 140	id = q[i].id; 141	l = q[i].l; 142	r = q[i].r; 143 144	if (pr&lt;r) 145	{ 146	for ( int j = pr+1 ; j &lt;= r ; j++) 147	update(j,1); 148	} 149	else 150	{ 151	for ( int j = r+1 ; j &lt;= pr ; j++) 152	update(j,-1); 153	} 154	pr = r; 155 156	if (pl&lt;l) 157	{ 158	for ( int j = pl ; j &lt;= l-1 ; j ++) 159	update(j,-1); 160	} 161	else 162	{ 163	for ( int j = l ; j &lt;= pl-1 ; j++) 164	update(j,1); 165	} 166	pl = l; 167 168	ans[id] = p; 169	} 170 171	for ( int i = 1 ;i &lt;= m ; i++) printf(&#34;%d\n&#34;,ans[i]); 172 173	} 174 175 176 #ifndef ONLINE_JUDGE 177 fclose(stdin); 178 #endif 179 return 0; 180}

