0; 92	int id,l,r; 93	sum = 0 ; //不小心又定义了个局部变量2333 94	for ( int i = 1 ; i &lt;= m ; i++) 95	{ 96	id = q[i].id; 97	l = q[i].l; 98	r = q[i].r; 99 100	if (r&lt;pr) 101	{ 102	for ( int j = r+1 ; j &lt;= pr ; j++) update(j,-1); 103	} 104	else 105	{ 106	for ( int j = pr +1 ; j &lt;= r ; j++) update(j,1); 107	} 108 109	pr = r; 110 111	// cout&lt;&lt;&#34;sum1:&#34;&lt;&lt;sum&lt;&lt;endl; 112 113	if (l&lt;pl) 114	{ 115	for ( int j = l ; j &lt;= pl-1 ; j++) update(j,1); 116	} 117	else 118	{ 119	for ( int j = pl ; j &lt;= l-1 ; j++) update(j,-1); 120	} 121 122	pl = l; 123//	cout&lt;&lt;&#34;sum2:&#34;&lt;&lt;sum&lt;&lt;endl; 124	ans[id] = sum; 125 126	// cout&lt;&lt;endl; 127	} 128 129	for ( int i = 1 ; i &lt;= m ;i ++) printf(&#34;%d\n&#34;,ans[i]); 130 131 #ifndef ONLINE_JUDGE 132 fclose(stdin); 133 #endif 134 return 0; 135}

