题意：有m个部门，每个部分s[i]个人，HW在第h部门，现在要从这m个部门中挑选包括HW在内的n个人去参加比赛，问被挑选的人中有HW的队友（同部门的人）的概率是多少。如果m个部分的人数不够组成n人的球队，输出-1. # 思路：考虑一般情况。至少有一个队友的情况较多，应该从反面考虑，即没有一个队友的情况。选完HW以后面临的状态是：事件总数为从total(m个部门的人员之和)-1个人中选n-1个的方案数，包含的事件数目为从a(a=total-s[h])中选n-1个人包含的方案数。 可以看出分母相同，可以约掉。 # 然后对于边界情况，首先判断total是否比n小。然后，如果a&lt;n-1,表示除去HW所在的h部分之外的人不可能组成n-1个人，也就是一定要选择HW的队友，概率为1.
1/* *********************************************** 2Author :111qqz 3Created Time :2016年02月03日 星期三 17时56分30秒 4File Name :code/cf/problem/107B.cpp 5************************************************ */ 6 7#include &lt;cstdio&gt; 8#include &lt;cstring&gt; 9#include &lt;iostream&gt; 10#include &lt;algorithm&gt; 11#include &lt;vector&gt; 12#include &lt;queue&gt; 13#include &lt;set&gt; 14#include &lt;map&gt; 15#include &lt;string&gt; 16#include &lt;cmath&gt; 17#include &lt;cstdlib&gt; 18#include &lt;ctime&gt; 19#define fst first 20#define sec second 21#define lson l,m,rt&lt;&lt;1 22#define rson m+1,r,rt&lt;&lt;1|1 23#define ms(a,x) memset(a,x,sizeof(a)) 24typedef long long LL; 25#define pi pair &lt; int ,int &gt; 26#define MP make_pair 27 28using namespace std; 29const double eps = 1E-8; 30const int dx4[4]={1,0,0,-1}; 31const int dy4[4]={0,-1,1,0}; 32const int inf = 0x3f3f3f3f; 33const int M=1E3+7; 34int n ,m,h; 35int s[M]; 36int main() 37{ 38	#ifndef ONLINE_JUDGE 39	freopen(&#34;code/in.txt&#34;,&#34;r&#34;,stdin); 40 #endif 41 42	cin&gt;&gt;n&gt;&gt;m&gt;&gt;h; 43	for ( int i = 1 ; i &lt;= m ; i++) cin&gt;&gt;s[i]; 44 45	double total = 0; 46	for ( int i =1 ; i &lt;= m ; i++) 47	{ 48	total+=s[i]; 49	} 50	if (total&lt;n) 51	{ 52	puts(&#34;-1&#34;); 53	return 0; 54	} 55	total--; 56	n--; 57	s[h]--; //减去那个人。 58	double a = total - s[h]; 59	double ans = 1.0; 60//	cout&lt;&lt;&#34;total:&#34;&lt;&lt;total&lt;&lt;&#34; a:&#34;&lt;&lt;a&lt;&lt;endl; 61	if (a&lt;n) //s[h]队外的人无法满足剩余的要求。 62	{ 63	puts(&#34;1&#34;); 64	return 0; 65	} 66	for ( int i = 1 ; i &lt;= n ; i++) 67	{ 68	ans = ans *(a*1.0/total*1.0); 69//	cout&lt;&lt;&#34;ans:&#34;&lt;&lt;ans&lt;&lt;endl; 70	a--; 71	total--; 72	} 73	printf(&#34;%.10f&#34;,1-ans); 74 75 #ifndef ONLINE_JUDGE 76 fclose(stdin); 77 #endif 78 return 0; 79}

http://codeforces.com/problemset/problem/453/A 题意：m面筛子，每面点数出现的概率相同，连续投掷n次，问出现的最大值的数学期望。 思路：手写样例。。。发现答案为 。。。记得把（1/m）^n放进去。
观察答案，可以这样理解（我是用样例推出公式后理解。。。数学差的人心好累）：如果i为最大值，那么n次每次必须投掷出1..i的点数，概率为 (i/m)^n,但是要至少有一个投掷成i，也就是要减去所有的数都是1..i-1中的情况（概率 为((i-1)/m)^n），
1/* *********************************************** 2Author :111qqz 3Created Time :2016年02月02日 星期二 05时17分24秒 4File Name :code/cf/problem/453A.cpp 5************************************************ */ 6 7#include &lt;cstdio&gt; 8#include &lt;cstring&gt; 9#include &lt;iostream&gt; 10#include &lt;algorithm&gt; 11#include &lt;vector&gt; 12#include &lt;queue&gt; 13#include &lt;set&gt; 14#include &lt;map&gt; 15#include &lt;string&gt; 16#include &lt;cmath&gt; 17#include &lt;cstdlib&gt; 18#include &lt;ctime&gt; 19#define fst first 20#define sec second 21#define lson l,m,rt&lt;&lt;1 22#define rson m+1,r,rt&lt;&lt;1|1 23#define ms(a,x) memset(a,x,sizeof(a)) 24typedef long long LL; 25#define pi pair &lt; int ,int &gt; 26#define MP make_pair 27 28using namespace std; 29const double eps = 1E-8; 30const int dx4[4]={1,0,0,-1}; 31const int dy4[4]={0,-1,1,0}; 32const int inf = 0x3f3f3f3f; 33const int N=1E5+7; 34double ans; 35int n ,m; 36double p1[N],p2[N]; 37int main() 38{ 39	#ifndef ONLINE_JUDGE 40	freopen(&#34;code/in.txt&#34;,&#34;r&#34;,stdin); 41 #endif 42 43	cin&gt;&gt;m&gt;&gt;n; 44	ans = 0; 45	for ( int i = 1 ; i &lt;= m ; i++) 46	{ 47	ans +=i*(pow(i*1.0/m,n*1.0)-pow((i-1)*1.0/m,n*1.0)); 48	} 49	printf(&#34;%.10f\n&#34;,ans); 50 51 #ifndef ONLINE_JUDGE 52 fclose(stdin); 53 #endif 54 return 0; 55}

