https://uva.onlinejudge.org/index.php?option=com_onlinejudge&Itemid;=8&page;=show_problem&problem;=1726 题意：给出26个大写字母的权值，要求构造一个长度为n（n不超过210）的字符串。并且满足奇数位置只能放元音字母，偶数位置只能放辅音字母，且每个元音字母最多放21次，每个辅音字母最多放5次，要求构造的字符串的权值之和最小，在权值最小的前提下字典序最小。
思路：贪心。一开始错误得以为不是完整得不能交换（也就是不完整的字母只能放在最后，这是错误的）。但实际上只要每个字母的数量不变，那么就不影响权值。所以做法是，奇数位置偶数位置分别搞，先把构成字符串的字母按次存入，然后排序一下，输出即可。
1/* *********************************************** 2Author :111qqz 3Created Time :2016年01月26日 星期二 15时10分28秒 4File Name :code/uva/10785.cpp 5************************************************ */ 6 7#include &lt;cstdio&gt; 8#include &lt;cstring&gt; 9#include &lt;iostream&gt; 10#include &lt;algorithm&gt; 11#include &lt;vector&gt; 12#include &lt;queue&gt; 13#include &lt;set&gt; 14#include &lt;map&gt; 15#include &lt;string&gt; 16#include &lt;cmath&gt; 17#include &lt;cstdlib&gt; 18#include &lt;ctime&gt; 19#define fst first 20#define sec second 21#define lson l,m,rt&lt;&lt;1 22#define rson m+1,r,rt&lt;&lt;1|1 23#define ms(a,x) memset(a,x,sizeof(a)) 24typedef long long LL; 25#define pi pair &lt; int ,int &gt; 26#define MP make_pair 27 28using namespace std; 29const double eps = 1E-8; 30const int dx4[4]={1,0,0,-1}; 31const int dy4[4]={0,-1,1,0}; 32const int inf = 0x3f3f3f3f; 33 34 35char a[30],b[30]; 36char oddans[210],evenans[210]; 37int n; 38void pre() 39{ 40 a[1]=&#39;A&#39;; 41 a[2]=&#39;U&#39;; 42 a[3]=&#39;E&#39;; 43 a[4]=&#39;O&#39;; 44 a[5]=&#39;I&#39;; 45 46 b[1]=&#39;J&#39;; 47 b[2]=&#39;S&#39;; 48 b[3]=&#39;B&#39;; 49 b[4]=&#39;K&#39;; 50 b[5]=&#39;T&#39;; 51 b[6]=&#39;C&#39;; 52 b[7]=&#39;L&#39;; 53 b[8]=&#39;D&#39;; 54 b[9]=&#39;M&#39;; 55 b[10]=&#39;V&#39;; 56 b[11]=&#39;N&#39;; 57 b[12]=&#39;W&#39;; 58 b[13]=&#39;F&#39;; 59 b[14]=&#39;X&#39;; 60 b[15]=&#39;G&#39;; 61 b[16]=&#39;P&#39;; 62 b[17]=&#39;Y&#39;; 63 b[18]=&#39;H&#39;; 64 b[19]=&#39;Q&#39;; 65 b[20]=&#39;Z&#39;; 66 b[21]=&#39;R&#39;; 67 68 69} 70 71void solve () 72{ 73 int odd = (n+1)/2; 74 int even = n/2; 75 76 int vowa = odd/21; 77 int vowr = odd; 78 int cona = even/5; 79 int conr = even%5; 80 81 int cnt = 0 ; 82 for ( int i = 1 ; i &lt;= vowa ; i++) 83 { 84	for ( int j =1 ; j &lt;=21 ; j++) 85	{ 86	cnt++; 87	oddans[cnt] = a[i]; 88	} 89 } 90 91 for ( int i = 1 ; i &lt;=vowr ; i++) 92 { 93	cnt++; 94	oddans[cnt]=a[vowa+1]; 95 } 96 97 cnt = 0 ; 98 for ( int i = 1 ; i &lt;= cona ; i++) 99 { 100	for ( int j = 1 ; j &lt;= 5 ; j++) 101	{ 102	cnt++; 103	evenans[cnt]=b[i]; 104	} 105 } 106 for ( int i = 1 ; i &lt;=conr ; i++) 107 { 108	cnt++; 109	evenans[cnt]=b[cona+1]; 110 } 111 112 sort(oddans+1,oddans+odd+1); 113 sort(evenans+1,evenans+even+1); 114 115 for ( int i = 1 ;i &lt;= n ; i++) 116 { 117	if (i%2==1) 118	{ 119	printf(&#34;%c&#34;,oddans[i/2+1]); 120	} 121	else 122	{ 123	printf(&#34;%c&#34;,evenans[i/2]); 124	} 125 } 126 puts(&#34;&#34;); 127} 128 129int main() 130{ 131	#ifndef ONLINE_JUDGE 132	freopen(&#34;code/in.txt&#34;,&#34;r&#34;,stdin); 133 #endif 134	pre(); 135	//cout&lt;&lt;good&lt;&lt;endl; 136	int T; //之前想错了。以为不是完整的就必须在最后。但是实际上只要数量不变就不影响权值和。那么在这个前提下就应该把非完整的字典序小的放在前面。 137	cin&gt;&gt;T; 138	int cas = 0 ; 139	while (T--) 140	{ 141	printf(&#34;Case %d: &#34;,++cas); 142	scanf(&#34;%d&#34;,&amp;n); 143	solve(); 144	} 145 146 147 148 #ifndef ONLINE_JUDGE 149 fclose(stdin); 150 #endif 151 return 0; 152}

https://uva.onlinejudge.org/index.php?option=com_onlinejudge&Itemid=8&page=show_problem&problem=92 题意：给出一段文字，包含若干个单词，以&rsquo;#&lsquo;结束。按照字典序输出所有的ananagrams。所谓ananagram，是指经过任意的重排后，不能得到这段文字中的另一个单词（不区分大小写） 思路：首先是字符串的读入&hellip;可以整行读入然后用空格分隔单词。由于补区分大小写，所以要都转化成小写&hellip;但是输出的时候要输出原始，所以还记得保留一份。而且要能够通过新的找到原始的（我用了一个toori的map&lt;string,string&gt;来实现） 然后最关键的部分是如何判断两个单词经过重排是否能一样&hellip;
我的做法是构造一个hash函数&hellip;一个单词的hash值等于对应字母的顺序的平方和&hellip;效果还不错？
单词和hash值一一对应&hellip;最大也就9E5,可以存的下。然后统计每个hash值出现的次数。对于那些只出现一次的，就是我们要的答案。
