al; 98	} 99	sscanf(in.c_str(),&#34;%d&#34;,&amp;val); 100	cnt++; 101	a[cnt]=val; 102 103	for ( int i = 1 ; i &lt;= cnt ; i++) cout&lt;&lt;a[i]&lt;&lt;&#34; &#34;; 104	cout&lt;&lt;endl; 105	//hash 106	for ( int i = 1 ; i &lt;= cnt ; i++) 107	{ 108	q[i].value = a[i]; 109	q[i].id = i ; 110	} 111 112	sort(q+1,q+cnt+1,cmp1); 113	int hashnum = 0; 114	for ( int i = 1 ; i &lt;=cnt ; i++) 115	{ 116	hashnum++; 117	q[i].value = hashnum; 118	} 119	sort(q+1,q+cnt+1,cmp2); 120 121	//check hash 122//	for ( int i =1 ; i &lt;= cnt ; i++) cout&lt;&lt;&#34;q[i].val:&#34;&lt;&lt;q[i].value&lt;&lt;&#34; &#34;; 123 124 125	for ( int i = 1 ; i &lt;= cnt ; i++) 126	{ 127	pos[q[i].value] = i ; 128	} 129 130	// print(cnt); 131	for ( int i = cnt ; i &gt;=1 ; i--) 132	{ 133	if (pos[i]==i) continue; 134	if (pos[i]==1) 135	{ 136	printf(&#34;%d &#34;,cnt+1-i); 137	flip2(i); 138	// print(cnt); 139	getpos(cnt); 140 141	} 142	else 143	{ 144	printf(&#34;%d &#34;,cnt+1-pos[i]); 145	flip2(pos[i]); 146	// print(cnt); 147	getpos(cnt); 148	printf(&#34;%d &#34;,cnt+1-i); 149	flip2(i); 150	// print(cnt); 151	getpos(cnt); 152	} 153	} 154	puts(&#34;0&#34;); 155 156 157 158	} 159 160 161 #ifndef ONLINE_JUDGE 162 fclose(stdin); 163 #endif 164 return 0; 165}

