http://codeforces.com/contest/22/problem/C 题意：要求用n个点m条边构造一个不允许有重边的图，满足当去掉点v的时候，剩下的n-1个不联通。如果有答案输出任意，没答案输出-1. 思路：首先如果n个点要联通。。至少有n-1条边，此时为一棵树。但是是不是边越多越好呢？显然是不可以的。满足去掉一个点使得n-1个点不联通的情况为，存在一个点u只和v相连，不和任意任何其他点相连，那么当去掉v点，u点就变成不可到达了。边数最多的情况就是，除了v点以外的n-1个点，每个点的度都是n-2(去掉自身以及u点还有n-2个点)，，那么除去u点以外的n-1个点的度数就是（n-1）(n-2)，边数则为(n-1)(n-2)/2，再加一条连接u的边，所以图的最大边数为(n-1)*(n-2)/2+1，最小为n-1.
如果有解，那么接下来的问题是构造。
我是按照如下方式构造的：
先构造一条链，将u点放在第一个，v点放在第二个。不妨当v=1时令u=2,否则u=1;
m-=n-1,如果m还有剩余，那么从第二个点开始，一直到第n-2个点，每个点与至少隔1个点的其他点相连，直到边数没有剩余。
1/* *********************************************** 2Author :111qqz 3Created Time :2015年12月30日 星期三 20时36分06秒 4File Name :code/cf/problem/22C.cpp 5************************************************ */ 6 7#include &lt;cstdio&gt; 8#include &lt;cstring&gt; 9#include &lt;iostream&gt; 10#include &lt;algorithm&gt; 11#include &lt;vector&gt; 12#include &lt;queue&gt; 13#include &lt;set&gt; 14#include &lt;map&gt; 15#include &lt;string&gt; 16#include &lt;cmath&gt; 17#include &lt;cstdlib&gt; 18#include &lt;ctime&gt; 19#define fst first 20#define sec second 21#define lson l,m,rt&lt;&lt;1 22#define rson m+1,r,rt&lt;&lt;1|1 23#define ms(a,x) memset(a,x,sizeof(a)) 24typedef long long LL; 25#define pi pair &lt; int ,int &gt; 26#define MP make_pair 27 28using namespace std; 29const double eps = 1E-8; 30const int dx4[4]={1,0,0,-1}; 31const int dy4[4]={0,-1,1,0}; 32const int inf = 0x3f3f3f3f; 33const int N=1E5+7; 34int n,m,v; 35int a[N]; 36int main() 37{ 38	#ifndef ONLINE_JUDGE 39	freopen(&#34;code/in.txt&#34;,&#34;r&#34;,stdin); 40 #endif 41	cin&gt;&gt;n&gt;&gt;m&gt;&gt;v; 42	if (m&lt;n-1||m&gt;((n-1)*(n-2)/2+1)) 43	{ 44	puts(&#34;-1&#34;); 45	return 0; 46	} 47 48	for ( int i = 1 ; i &lt;= n ; i++) 49	{ 50	a[i] = i ; 51	if (i==2) 52	{ 53	a[i]=v; 54	} 55	if (i==v) 56	{ 57	a[i]=2; 58	} 59	} 60	for ( int i = 1 ; i &lt;= n-1 ; i++) 61	{ 62	printf(&#34;%d %d\n&#34;,a[i],a[i+1]); 63	} 64	m-=n-1; 65 66	int cnt = 0 ; 67	for ( int i = 2 ; i &lt;= n-2 ; i ++) 68	{ 69	if (cnt&gt;m) break; 70	for ( int j = i+2 ; j &lt;= n ; j++) 71	{ 72	cnt++; 73	if (cnt&gt;m) break; 74	printf(&#34;%d %d\n&#34;,a[i],a[j]); 75	} 76	} 77 78 79 #ifndef ONLINE_JUDGE 80 fclose(stdin); 81 #endif 82 return 0; 83}

http://codeforces.com/contest/30/problem/C 题意：给出n个target在一个二维平面上。给出每个target的坐标，出现的时间，以及击中的概率。target出现之后就会瞬间消失，枪移动的单位速度为1，射击不需要时间。问能击中的target的最大期望是多少。
思路：路径dp。。。按照时间升序排列。 dp[i]表示到第i个target出现的时候的期望。
1/* *********************************************** 2Author :111qqz 3Created Time :2015年12月29日 星期二 18时14分45秒 4File Name :code/cf/problem/30C.cpp 5************************************************ */ 6 7#include &lt;cstdio&gt; 8#include &lt;cstring&gt; 9#include &lt;iostream&gt; 10#include &lt;algorithm&gt; 11#include &lt;vector&gt; 12#include &lt;queue&gt; 13#include &lt;set&gt; 14#include &lt;map&gt; 15#include &lt;string&gt; 16#include &lt;cmath&gt; 17#include &lt;cstdlib&gt; 18#include &lt;ctime&gt; 19#define fst first 20#define sec second 21#define lson l,m,rt&lt;&lt;1 22#define rson m+1,r,rt&lt;&lt;1|1 23#define ms(a,x) memset(a,x,sizeof(a)) 24typedef long long LL; 25#define pi pair &lt; int ,int &gt; 26#define MP make_pair 27 28using namespace std; 29const double eps = 1E-8; 30const int dx4[4]={1,0,0,-1}; 31const int dy4[4]={0,-1,1,0}; 32const int inf = 0x3f3f3f3f; 33const int N=1E3+7; 34int n; 35double dp[N]; 36int dblcmp(double d) 37{ 38 return d&lt;-eps?-1:d&gt;eps; 39} 40struct point 41{ 42 int x,y,t; 43 double p; 44 45 void input() 46 { 47	scanf(&#34;%d %d %d&#34;,&amp;x,&amp;y,&amp;t); 48	scanf(&#34;%lf&#34;,&amp;p); 49 } 50 51 double dis(point p) 52 { 53	return sqrt((x-p.x)*(x-p.x)+(y-p.y)*(y-p.y)); 54 } 55 56 bool operator &lt;(point p)const 57 { 58	return t&lt;p.t; 59 } 60}p[N]; 61int main() 62{ 63	#ifndef ONLINE_JUDGE 64	freopen(&#34;code/in.txt&#34;,&#34;r&#34;,stdin); 65 #endif 66	cin&gt;&gt;n; 67	for ( int i = 1 ; i &lt;= n ; i++) p[i].input(); 68 69	sort(p+1,p+n+1); 70 71	double ans=0; 72	for ( int i = 1 ; i &lt;= n ; i++) 73	{ 74	dp[i] = p[i].p; 75	for ( int j = 1 ; j &lt; i ; j++) 76	{ 77	if (dblcmp(p[i].dis(p[j])-p[i].t+p[j].t)&lt;=0) 78	dp[i] = max(dp[i],dp[j]+p[i].p); 79	} 80	ans = max(dp[i],ans); 81	} 82	printf(&#34;%.10f\n&#34;,ans); 83 84 #ifndef ONLINE_JUDGE 85 fclose(stdin); 86 #endif 87 return 0; 88}

http://codeforces.com/contest/12/problem/C 题意：有n个价格价格，m个要买的东西（可能有相同的种类，设为k种），把n个标签中拿出k个给个贴上。。。问最大价钱和最少价钱分别是多少。 思路：贪心。不过要按照map的value排序。。然后发现其实不用排序。。因为map的key值其实不影响。
vector降序排列的话。。直接 sort(v.rbegin(),v.rend());就好。
1/* *********************************************** 2Author :111qqz 3Created Time :2015年12月29日 星期二 15时30分54秒 4File Name :code/cf/problem/12C.cpp 5************************************************ */ 6 7#include &lt;cstdio&gt; 8#include &lt;cstring&gt; 9#include &lt;iostream&gt; 10#include &lt;algorithm&gt; 11#include &lt;vector&gt; 12#include &lt;queue&gt; 13#include &lt;set&gt; 14#include &lt;map&gt; 15#include &lt;string&gt; 16#include &lt;cmath&gt; 17#include &lt;cstdlib&gt; 18#include &lt;ctime&gt; 19#define fst first 20#define sec second 21#define lson l,m,rt&lt;&lt;1 22#define rson m+1,r,rt&lt;&lt;1|1 23#define ms(a,x) memset(a,x,sizeof(a)) 24typedef long long LL; 25#define pi pair &lt; int ,int &gt; 26#define MP make_pair 27 28using namespace std; 29const double eps = 1E-8; 30const int dx4[4]={1,0,0,-1}; 31const int dy4[4]={0,-1,1,0}; 32const int inf = 0x3f3f3f3f; 33const int N=105; 34int n,m; 35map&lt;string,int&gt;mp; 36int a[N]; 37map&lt;string,int&gt;::iterator it; 38vector&lt;int &gt;v; 39int main() 40{ 41	#ifndef ONLINE_JUDGE 42	freopen(&#34;code/in.txt&#34;,&#34;r&#34;,stdin); 43 #endif 44	mp.clear(); 45	cin&gt;&gt;n&gt;&gt;m; 46	for ( int i = 0; i &lt; n ; i++) cin&gt;&gt;a[i]; 47	sort(a,a+n); 48 49	for ( int i = 0 ; i &lt; m ; i++) 50	{ 51	string tmp; 52	cin&gt;&gt;tmp; 53	if (!mp[tmp]) 54	{ 55	mp[tmp] = 1; 56	} 57	else 58	{ 59	mp[tmp]++; 60	} 61	} 62 63 64	for ( it = mp.begin() ; it !=mp.end() ; it++) 65	{ 66	v.push_back(it-&gt;second); 67	} 68	int mi,mx; 69	mi=mx=0; 70	sort(v.rbegin(),v.rend()); 71	for ( int i = 0 ; i &lt; v.size() ; i++) 72	{ 73	mi +=a[i]*v[i]; 74//	cout&lt;&lt;&#34;v[i]:&#34;&lt;&lt;v[i]&lt;&lt;endl; 75	mx +=a[n-1-i]*v[i];\ 76	//cout&lt;&lt;&#34;mi:&#34;&lt;&lt;mi&lt;&lt;&#34; mx:&#34;&lt;&lt;mx&lt;&lt;endl; 77	} 78	cout&lt;&lt;mi&lt;&lt;&#34; &#34;&lt;&lt;mx&lt;&lt;endl; 79 80 81 82 #ifndef ONLINE_JUDGE 83 fclose(stdin); 84 #endif 85 return 0; 86}

