http://codeforces.com/contest/599/problem/D 题意：给出总的方格数x，问有多少种不同尺寸的矩形满足题意，输出方案数和长宽（3,5和5,3算两种） 思路：比赛的时候gg了。。其实稍微在纸上推一下。就会得到对于n,m的矩形，一共会有-nnn+3nnm+n+3n*m的方格。数量级是n3。 我们可以实际跑一遍。发现对于x1E18的数量级，n不会超过1442550，1E6,可以搞。
需要注意的是，一个是会爆int,所以记得用long long
另一个是如果两个数相等，记得只输入一组，并且方案数-1
我是用set +pair存的答案。。反向遍历set的时候要用reserve_iterator&hellip;
1/* *********************************************** 2Author :111qqz 3Created Time :2015年12月23日 星期三 15时54分37秒 4File Name :code/cf/#332/D.cpp 5************************************************ */ 6 7#include &lt;cstdio&gt; 8#include &lt;cstring&gt; 9#include &lt;iostream&gt; 10#include &lt;algorithm&gt; 11#include &lt;vector&gt; 12#include &lt;queue&gt; 13#include &lt;set&gt; 14#include &lt;map&gt; 15#include &lt;string&gt; 16#include &lt;cmath&gt; 17#include &lt;cstdlib&gt; 18#include &lt;ctime&gt; 19#define fst first 20#define sec second 21#define lson l,m,rt&lt;&lt;1 22#define rson m+1,r,rt&lt;&lt;1|1 23#define ms(a,x) memset(a,x,sizeof(a)) 24typedef long long LL; 25#define pi pair &lt; LL ,LL &gt; 26#define MP make_pair 27 28using namespace std; 29const double eps = 1E-8; 30const int dx4[4]={1,0,0,-1}; 31const int dy4[4]={0,-1,1,0}; 32const int inf = 0x3f3f3f3f; 33LL x; 34LL cur; 35const LL MAXN = 1442550; 36set&lt;pi&gt;se; 37LL cal( LL n,LL m) 38{ 39 LL res = -n*n*n+3*n*n*m+3*n*m+n; 40 return res; 41} 42int square = -1; 43int main() 44{ 45	#ifndef ONLINE_JUDGE 46	freopen(&#34;code/in.txt&#34;,&#34;r&#34;,stdin); 47 #endif 48//	for ( LL i = 1 ; ; i++) 49//	{ 50//	cur = cal(i,i); 51//	// cout&lt;&lt;&#34;i:&#34;&lt;&lt;i&lt;&lt;&#34; cur:&#34;&lt;&lt;cur&lt;&lt;endl; 52//	if (cur&gt;1E18) 53//	{ 54//	cout&lt;&lt;i&lt;&lt;endl; 55//	break; 56//	} 57// 58//	} 59	cin&gt;&gt;x; 60	x = x*6; 61	for ( LL i = 1 ; cal(i,i)&lt;=x ; i++) 62	{ 63	LL tmp = (x-i+i*i*i)%(3*i*i+3*i); 64	// cout&lt;&lt;&#34;i:&#34;&lt;&lt;i&lt;&lt;&#34; tmp:&#34;&lt;&lt;tmp&lt;&lt;endl; 65	if (tmp==0) 66	{ 67	se.insert(make_pair(i,(x-i+i*i*i)/(3*i*i+3*i))); 68	if (i==(x-i+i*i*i)/(3*i*i+3*i)) square = 1; 69 70	} 71	} 72	if (square==1) 73	cout&lt;&lt;se.size()*2-1&lt;&lt;endl; 74	else cout&lt;&lt;se.size()*2&lt;&lt;endl; 75	set&lt;pi&gt;::iterator it; 76	for (it = se.begin(); it!=se.end() ;it++) 77	{ 78 79	cout&lt;&lt;(*it).fst&lt;&lt;&#34; &#34;&lt;&lt;(*it).sec&lt;&lt;endl; 80	} 81	set&lt;pi&gt;::reverse_iterator it2; //反向遍历要用反向迭代器。。。右忘记了。。。。 82	for ( it2 =se.rbegin() ;it2 !=se.rend() ; it2 ++) 83	{ 84	if (square==1) 85	{ 86	square = 2; 87	continue; 88	} 89 90 91	cout&lt;&lt;(*it2).sec&lt;&lt;&#34; &#34;&lt;&lt;(*it2).fst&lt;&lt;endl; 92	} 93 94 95 #ifndef ONLINE_JUDGE 96 fclose(stdin); 97 #endif 98 return 0; 99}

http://codeforces.com/problemset/problem/466/C 题意：给定一个序列。要将序列分成三个非零的连续部分，使得三部分的和相等。问有多少中分法。 思路：首先可以知道，如果是序列的和不为3的倍数，那么一定无解，输出0.设序列的和为sum,那么每一部分的和就应该为sum/3。我们可以预处理出从1开始的和为sum/3的点（我开了数组表示前缀和。。想了下其实不用。。我只需要点的信息。。所以用一个变量表示即可），将点的下标存在p[i]里。对于每一个p[i]，我想要知道比p[i]大且补与p[i]相邻的点中，有多少个j，使得从j到n的和为sum/3。因为如果有两部分的和都为sum/3，那么剩下的那部分也一定为sum/3.然后要知道有多少个满足题意的j,我们可以从后往前扫一遍，标记从n开始往前扫，和为sum/3的点，可以用一个0,1数组表示。如果和为sum/3，那么标记为1，否则为0.然后再用一个类似前缀和的思路。再开一个数组c记录从j到n有的和为多少，也就是从j到n有多少个点满足该点到n的和为sum/3.
预处理完这些之后。只需要从前往后扫一遍p[i]，然后ans+=c[p[i]+2]即可。
1/* *********************************************** 2Author :111qqz 3Created Time :2015年12月15日 星期二 20时28分44秒 4File Name :code/cf/problem/466C.cpp 5************************************************ */ 6 7#include &lt;cstdio&gt; 8#include &lt;cstring&gt; 9#include &lt;iostream&gt; 10#include &lt;algorithm&gt; 11#include &lt;vector&gt; 12#include &lt;queue&gt; 13#include &lt;set&gt; 14#include &lt;map&gt; 15#include &lt;string&gt; 16#include &lt;cmath&gt; 17#include &lt;cstdlib&gt; 18#include &lt;ctime&gt; 19#define fst first 20#define sec second 21#define lson l,m,rt&lt;&lt;1 22#define rson m+1,r,rt&lt;&lt;1|1 23#define ms(a,x) memset(a,x,sizeof(a)) 24typedef long long LL; 25#define pi pair &lt; int ,int &gt; 26#define MP make_pair 27 28using namespace std; 29const double eps = 1E-8; 30const int dx4[4]={1,0,0,-1}; 31const int dy4[4]={0,-1,1,0}; 32const int inf = 0x3f3f3f3f; 33const int N=5E5+7; 34int n; 35int a[N]; 36LL sum[N],rsum[N]; 37int p[N],rp[N]; 38int cnt,rcnt; 39int b[N]; 40int c[N]; 41LL ans; 42LL solve() 43{ 44 LL total = sum[n]; 45 if (total%3!=0) return 0; 46 LL ave = total/3; 47 cnt = 0 ; 48 for ( int i = 1 ; i &lt;= n ; i++) 49 { 50	if (sum[i]==ave) 51	{ 52	cnt++; 53	p[cnt] = i; 54	// cout&lt;&lt;&#34;i:&#34;&lt;&lt;i&lt;&lt;endl; 55	} 56 } 57 ms(b,0); 58 for ( int i = n ; i &gt;= 1 ; i--) 59 { 60	if (rsum[i]==ave) 61	{ 62	b[i] = 1; //b[i]为1表示可以，为0表示不可以。 63	} 64 } 65 c[n] = b[n]; //c[i]表示i..n一共有多少个b[i]可以。 66 for ( int i = n-1 ; i &gt;= 1 ; i--) 67 { 68	c[i] = c[i+1] + b[i]; 69 } 70 71 72 LL res = 0 ; 73 for ( int i = 1 ; i &lt;= cnt ; i++) 74 { 75	res+= c[p[i]+2]; //中间至少隔一个，因为要分成三组。 76 } 77 return res; 78 79} 80int main() 81{ 82	#ifndef ONLINE_JUDGE 83	freopen(&#34;code/in.txt&#34;,&#34;r&#34;,stdin); 84 #endif 85 86	cin&gt;&gt;n; 87	sum[0] = 0 ; 88 89	for ( int i = 1 ; i &lt;= n ; i++) 90	{ 91	scanf(&#34;%d&#34;,&amp;a[i]); 92	sum[i] = sum[i-1] + a[i]; 93	} 94	rsum[n+1] = 0 ; 95	for ( int i = n ; i &gt;= 1 ; i --) 96	{ 97	rsum[i] = rsum[i+1] + a[i]; 98	} 99	ans = solve(); 100	cout&lt;&lt;ans&lt;&lt;endl; 101 102 103 #ifndef ONLINE_JUDGE 104 fclose(stdin); 105 #endif 106 return 0; 107}

http://codeforces.com/problemset/status 题意：n行m列的道路网络。共n*m条道路。每条道路都是单向的.问从任何一个路口出发能否到达其他的任何一个路口。
思路：需要注意的是。我从A点能到达B点，不代表B也能到达A.也就是说，某些点满足可以遍历所有点是不够的，只有当所有点都满足才可以。
1/* *********************************************** 2Author :111qqz 3Created Time :2015年12月07日 星期一 08时55分48秒 4File Name :code/cf/problem/475B.cpp 5************************************************ */ 6 7#include &lt;cstdio&gt; 8#include &lt;cstring&gt; 9#include &lt;iostream&gt; 10#include &lt;algorithm&gt; 11#include &lt;vector&gt; 12#include &lt;queue&gt; 13#include &lt;set&gt; 14#include &lt;map&gt; 15#include &lt;string&gt; 16#include &lt;cmath&gt; 17#include &lt;cstdlib&gt; 18#include &lt;ctime&gt; 19#define fst first 20#define sec second 21#define lson l,m,rt&lt;&lt;1 22#define rson m+1,r,rt&lt;&lt;1|1 23#define ms(a,x) memset(a,x,sizeof(a)) 24typedef long long LL; 25 26 27 28using namespace std; 29const double eps = 1E-8; 30const int dx4[4]={1,0,0,-1}; 31const int dy4[4]={0,-1,1,0}; 32const int inf = 0x3f3f3f3f; 33const int N=25; 34int n,m; 35bool vis[N][N]; 36char hor[N],ver[N]; 37 38bool direrror (char ch,int d) 39{ 40 if (ch==&#39;v&#39;&amp;&amp;d==3) return true; 41 if (ch==&#39;^&#39;&amp;&amp;d==0) return true; 42 43 if (ch==&#39;&lt;&#39;&amp;&amp;d==2) return true; 44 if (ch==&#39;&gt;&#39;&amp;&amp;d==1) return true; 45 46	return false; 47} 48 49bool ok ( int x,int y) 50{ 51 if (x&gt;=0&amp;&amp;x&lt;n&amp;&amp;y&gt;=0&amp;&amp;y&lt;m&amp;&amp;!vis[x][y]) return true; 52 return false; 53} 54 55 56void dfs ( int x,int y) 57{ 58 vis[x][y] = true; 59 // cout&lt;&lt;&#34;x:&#34;&lt;&lt;x&lt;&lt;&#34; y:&#34;&lt;&lt;y&lt;&lt;endl; 60 for ( int i = 0 ; i &lt; 4 ; i++) 61 { 62	if (direrror(hor[x],i)) continue; 63	if (direrror(ver[y],i)) continue; 64 65	int nx = x + dx4[i]; 66	int ny = y + dy4[i]; 67	if (ok(nx,ny)) 68	{ 69	dfs(nx,ny); 70	} 71 } 72} 73 74bool solve ( int x,int y) 75{ 76 ms(vis,false); 77 dfs(x,y); 78 for ( int i = 0 ; i &lt; n ; i++) 79	for ( int j = 0 ; j &lt; m; j ++) 80	if (!vis[i][j]) return false; 81 return true; 82 83} 84int main() 85{ 86	#ifndef ONLINE_JUDGE 87	freopen(&#34;code/in.txt&#34;,&#34;r&#34;,stdin); 88 #endif 89 90 91	cin&gt;&gt;n&gt;&gt;m; //注意题目要求是从任意一点都可以到达其他任何点。 92	for ( int i = 0 ; i &lt; n ; i ++) cin&gt;&gt;hor[i]; 93	for ( int i = 0 ; i &lt; m ; i ++) cin&gt;&gt;ver[i]; 94 95	int cnt = 0 ; 96	bool ok = true; 97	for ( int i = 0 ; i&lt; n ; i++) 98	for ( int j = 0 ;j &lt; m; j++) 99	if (!solve(i,j)) 100	{ 101	ok = false; 102	break; 103	} 104//	cout&lt;&lt;&#34;cnt:&#34;&lt;&lt;cnt&lt;&lt;endl; 105	if (ok) 106	{ 107	puts(&#34;YES&#34;); 108	} 109	else 110	{ 111	puts(&#34;NO&#34;); 112	} 113 114 #ifndef ONLINE_JUDGE 115 fclose(stdin); 116 #endif 117 return 0; 118}

http://codeforces.com/problemset/problem/217/A 题意：有n个雪漂（那是啥？，从某个雪漂出发走直线，只有到达另一个雪飘才能停下来。问最少需要添加多少个雪漂，才能使得可以到达任何一个雪漂。 思路：横坐标相同或者纵坐标相同的两个点之间是可以到达的。先O(N2)扫一遍建图。记录这个森林中数的个数为cnt,cnt-1即为答案。因为对于任意两个不能相互到达的点。我们只需要再来一个雪漂就可以使得这两个点相互到达。
一遍AC，有点爽。
1/* *********************************************** 2Author :111qqz 3Created Time :2015年12月05日 星期六 20时18分23秒 4File Name :code/problem/217A.cpp 5************************************************ */ 6 7#include &lt;cstdio&gt; 8#include &lt;cstring&gt; 9#include &lt;iostream&gt; 10#include &lt;algorithm&gt; 11#include &lt;vector&gt; 12#include &lt;queue&gt; 13#include &lt;set&gt; 14#include &lt;map&gt; 15#include &lt;string&gt; 16#include &lt;cmath&gt; 17#include &lt;cstdlib&gt; 18#include &lt;ctime&gt; 19#define fst first 20#define sec second 21#define lson l,m,rt&lt;&lt;1 22#define rson m+1,r,rt&lt;&lt;1|1 23#define ms(a,x) memset(a,x,sizeof(a)) 24typedef long long LL; 25 26 27 28using namespace std; 29const double eps = 1E-8; 30const int dx4[4]={1,0,0,-1}; 31const int dy4[4]={0,-1,1,0}; 32const int inf = 0x3f3f3f3f; 33const int N=105; 34int n; 35bool vis[N]; 36int x[N],y[N]; 37 38vector&lt;int&gt;edge[N]; 39 40void dfs( int x) 41{ 42 vis[x] = true; 43 for ( int i = 0 ; i &lt; edge[x].size() ; i++) 44 { 45	int v = edge[x][i]; 46	if (!vis[v]) 47	{ 48	dfs(v); 49	} 50 } 51} 52int main() 53{ 54	#ifndef ONLINE_JUDGE 55	freopen(&#34;code/in.txt&#34;,&#34;r&#34;,stdin); 56 #endif 57 58	scanf(&#34;%d&#34;,&amp;n); 59	for ( int i = 0 ; i &lt; n ; i++) scanf(&#34;%d %d&#34;,&amp;x[i],&amp;y[i]); 60 61	for ( int i = 0 ; i &lt; n-1 ; i++) 62	{ 63	for ( int j = i+1 ; j &lt; n ; j++) 64	{ 65	if (x[i]==x[j]) 66	{ 67	edge[i].push_back(j); 68	edge[j].push_back(i); 69	} 70	if (y[i]==y[j]) 71	{ 72	edge[i].push_back(j); 73	edge[j].push_back(i); 74	} 75 76	} 77	} 78	ms(vis,false); 79	int cnt = 0 ; 80	for ( int i = 0 ; i &lt; n ; i++) 81	{ 82	if (!vis[i]) 83	{ 84	dfs(i); 85	cnt++; 86	} 87	} 88	cout&lt;&lt;cnt-1&lt;&lt;endl; 89 90 #ifndef ONLINE_JUDGE 91 fclose(stdin); 92 #endif 93 return 0; 94}

http://codeforces.com/problemset/problem/522/A 题意：给定某条消息的传播路径。问最远传播的距离。。 思路：其实就是问树的深度。。直接dfs就行了。。
存的时候用map&lt;string,vector &gt; mp;的方式存即可。
1/* *********************************************** 2Author :111qqz 3Created Time :2015年12月05日 星期六 16时41分41秒 4File Name :code/cf/problem/522A.cpp 5************************************************ */ 6 7#include &lt;cstdio&gt; 8#include &lt;cstring&gt; 9#include &lt;iostream&gt; 10#include &lt;algorithm&gt; 11#include &lt;vector&gt; 12#include &lt;queue&gt; 13#include &lt;set&gt; 14#include &lt;map&gt; 15#include &lt;string&gt; 16#include &lt;cmath&gt; 17#include &lt;cstdlib&gt; 18#include &lt;ctime&gt; 19#define fst first 20#define sec second 21#define lson l,m,rt&lt;&lt;1 22#define rson m+1,r,rt&lt;&lt;1|1 23#define ms(a,x) memset(a,x,sizeof(a)) 24typedef long long LL; 25 26 27 28using namespace std; 29const double eps = 1E-8; 30const int dx4[4]={1,0,0,-1}; 31const int dy4[4]={0,-1,1,0}; 32const int inf = 0x3f3f3f3f; 33const int N=2E2+7; 34map&lt;string,vector&lt;string&gt; &gt; mp; 35map&lt;string,bool&gt;vis; 36string from,to,nouse; 37int ans; 38int n; 39 40void dfs(string cur,int depth) 41{ 42// cout&lt;&lt;&#34;cur:&#34;&lt;&lt;cur&lt;&lt;&#34; depth:&#34;&lt;&lt;depth&lt;&lt;endl; 43 vis[cur] = true; 44 ans = max(ans,depth); 45 for ( int i = 0 ; i &lt; mp[cur].size() ; i++) 46 { 47	string v = mp[cur][i]; 48	if (!vis[v]) 49	dfs(v,depth+1); 50 } 51} 52 53string tran(string x) 54{ 55 int len = x.length(); 56 for ( int i = 0 ; i &lt; len ; i++) 57 { 58	if (x[i]&gt;=&#39;A&#39;&amp;&amp;x[i]&lt;=&#39;Z&#39;) 59	{ 60	x[i] = char(x[i]+32); 61	} 62 } 63 return x; 64} 65int main() 66{ 67	#ifndef ONLINE_JUDGE 68	freopen(&#34;code/in.txt&#34;,&#34;r&#34;,stdin); 69 #endif 70	mp.clear(); 71	scanf(&#34;%d&#34;,&amp;n); 72//	getchar(); 73	for ( int i = 0 ; i &lt; n ; i++) 74	{ 75	cin&gt;&gt;to&gt;&gt;nouse&gt;&gt;from; 76	to = tran(to); 77	from = tran(from); 78//	getchar(); 79	// cout&lt;&lt;&#34;to:&#34;&lt;&lt;to&lt;&lt;endl&lt;&lt;&#34; nouse:&#34;&lt;&lt;nouse&lt;&lt;endl&lt;&lt;&#34; from:&#34;&lt;&lt;from&lt;&lt;endl; 80	mp[from].push_back(to); 81	} 82	ans = 1; 83	dfs(&#34;polycarp&#34;,1); 84	printf(&#34;%d\n&#34;,ans); 85 86 #ifndef ONLINE_JUDGE 87 fclose(stdin); 88 #endif 89 return 0; 90}

题意：给定一个01串。要进行一次变换：选一段连续的非空的字串，将这段串的0和1反转（0变成1,1变成0） 然后问能得到的最长的0,1交替的序列的长度是多少（不一定连续）
比赛的时候想出来两种会将答案增加的可能情况。一种是10000001 中间有大于等于3个的连续字符，这样可以把中间反转一下，答案会+2 另外一种是 1001001 这样。。有至少两段的连续两个以上的相同字符被另一个字符隔开的情况。只要将1001001变成1010101。答案还是会+2。。。然后发现这两种情况实际上可以统一起来。即：有至少两段的连续相同字符。 注意000 也算有两段。 如果有两段或者以上，那么答案+2.
