;,&amp;q,&amp;p); 94 double r = p*1.0/q; 95 for ( int i = N-5 ; i &gt;= 1 ; i--) 96 { 97	if (r*f[i]&lt;=g[i]) 98	{ 99	cout&lt;&lt;i&lt;&lt;endl; 100	break; 101	} 102 } 103 104 105	return 0; 106}

